  add("geometry", "g3", 0, [{"type":"regular","q":"Translate the point $(2, 5)$ by $\\langle 6, -3 \\rangle$.","answer":"$(8, 2)$","solution":"Add the translation vector components to the point: $(2+6, 5-3) = (8, 2)$."},{"type":"regular","q":"Reflect $(−2, 8)$ over the x-axis.","answer":"$(−2, −8)$","solution":"Reflecting over the x-axis negates the y-coordinate: $(−2, −8)$."},{"type":"regular","q":"Translate $(−1, −4)$ by $\\langle −3, 7 \\rangle$.","answer":"$(−4, 3)$","solution":"Add vector components: $(−1−3, −4+7) = (−4, 3)$."},{"type":"regular","q":"Reflect $(6, −5)$ over the y-axis.","answer":"$(−6, −5)$","solution":"Reflecting over the y-axis negates the x-coordinate: $(−6, −5)$."},{"type":"regular","q":"Translate $(0, 0)$ by $\\langle 9, −2 \\rangle$.","answer":"$(9, −2)$","solution":"Adding the translation vector to the origin gives the vector itself: $(9, −2)$."},{"type":"regular","q":"Reflect $(−3, −7)$ over the x-axis.","answer":"$(−3, 7)$","solution":"Negate the y-coordinate: $(−3, 7)$."},{"type":"regular","q":"Translate $(7, 1)$ by $\\langle −5, −6 \\rangle$.","answer":"$(2, −5)$","solution":"Add vector components: $(7−5, 1−6) = (2, −5)$."},{"type":"regular","q":"Reflect $(4, 9)$ over the y-axis.","answer":"$(−4, 9)$","solution":"Negate the x-coordinate: $(−4, 9)$."},{"type":"regular","q":"Translate $(−6, 3)$ by $\\langle 2, 8 \\rangle$.","answer":"$(−4, 11)$","solution":"Add vector components: $(−6+2, 3+8) = (−4, 11)$."},{"type":"word","q":"A painting at coordinates $(3, 4)$ is moved 5 units left and 2 units down. What is its new position?","answer":"$(−2, 2)$","solution":"Translate by $\\langle −5, −2 \\rangle$: $(3−5, 4��2) = (−2, 2)$."},{"type":"word","q":"A point on a map is at $(8, −3)$. After reflecting it over the x-axis, where is it?","answer":"$(8, 3)$","solution":"Reflecting over the x-axis negates the y-coordinate: $(8, 3)$."},{"type":"word","q":"A bird starts at $(−2, 5)$ and flies 7 units right and 3 units up. Where does it land?","answer":"$(5, 8)$","solution":"Translate by $\\langle 7, 3 \\rangle$: $(−2+7, 5+3) = (5, 8)$."},{"type":"word","q":"A mirror image of point $(−4, 6)$ is created by reflecting over the y-axis. What are the coordinates?","answer":"$(4, 6)$","solution":"Reflecting over the y-axis negates the x-coordinate: $(4, 6)$."},{"type":"word","q":"A boat at $(1, −2)$ moves 4 units left and 5 units up. What is its new location?","answer":"$(−3, 3)$","solution":"Translate by $\\langle −4, 5 \\rangle$: $(1−4, −2+5) = (−3, 3)$."},{"type":"word","q":"A design point at $(9, −8)$ is reflected over the x-axis. Where does it end up?","answer":"$(9, 8)$","solution":"Negate the y-coordinate: $(9, 8)$."}]);
  add("geometry", "g3", 1, [{"type":"regular","q":"Rotate $(2, 0)$ by $90°$ counterclockwise about the origin.","answer":"$(0, 2)$","solution":"A $90°$ CCW rotation maps $(x, y) \\to (−y, x)$: $(2, 0) \\to (0, 2)$."},{"type":"regular","q":"Rotate $(1, 1)$ by $180°$ about the origin.","answer":"$(−1, −1)$","solution":"A $180°$ rotation maps $(x, y) \\to (−x, −y)$: $(1, 1) \\to (−1, −1)$."},{"type":"regular","q":"Rotate $(0, 5)$ by $90°$ counterclockwise about the origin.","answer":"$(−5, 0)$","solution":"Using $(x, y) \\to (−y, x)$: $(0, 5) \\to (−5, 0)$."},{"type":"regular","q":"Rotate $(−3, 0)$ by $180°$ about the origin.","answer":"$(3, 0)$","solution":"A $180°$ rotation maps $(x, y) \\to (−x, −y)$: $(−3, 0) \\to (3, 0)$."},{"type":"regular","q":"Rotate $(6, 1)$ by $270°$ counterclockwise about the origin.","answer":"$(1, −6)$","solution":"A $270°$ CCW rotation (or $90°$ CW) maps $(x, y) \\to (y, −x)$: $(6, 1) \\to (1, −6)$."},{"type":"regular","q":"Rotate $(−2, 4)$ by $90°$ counterclockwise about the origin.","answer":"$(−4, −2)$","solution":"Using $(x, y) \\to (−y, x)$: $(−2, 4) \\to (−4, −2)$."},{"type":"regular","q":"Rotate $(5, 3)$ by $180°$ about the origin.","answer":"$(−5, −3)$","solution":"A $180°$ rotation maps $(x, y) \\to (−x, −y)$: $(5, 3) \\to (−5, −3)$."},{"type":"regular","q":"Rotate $(−1, −5)$ by $270°$ counterclockwise about the origin.","answer":"$(−5, 1)$","solution":"Using $(x, y) \\to (y, −x)$: $(−1, −5) \\to (−5, 1)$."},{"type":"regular","q":"Rotate $(7, −2)$ by $90°$ counterclockwise about the origin.","answer":"$(2, 7)$","solution":"Using $(x, y) \\to (−y, x)$: $(7, −2) \\to (2, 7)$."},{"type":"word","q":"A clock hand points to $(4, 0)$. After rotating $90°$ counterclockwise, where does it point?","answer":"$(0, 4)$","solution":"A $90°$ CCW rotation maps $(4, 0) \\to (0, 4)$."},{"type":"word","q":"A satellite at position $(−3, 2)$ rotates $180°$ around Earth's center. What is its new position?","answer":"$(3, −2)$","solution":"A $180°$ rotation maps $(−3, 2) \\to (3, −2)$."},{"type":"word","q":"A dancer at $(2, 5)$ spins $270°$ counterclockwise. Where does the dancer end up?","answer":"$(5, −2)$","solution":"A $270°$ CCW rotation maps $(x, y) \\to (y, −x)$: $(2, 5) \\to (5, −2)$."},{"type":"word","q":"A wheel spoke at $(−6, 0)$ rotates $180°$ about the hub. Where is the spoke now?","answer":"$(6, 0)$","solution":"A $180°$ rotation maps $(−6, 0) \\to (6, 0)$."},{"type":"word","q":"A point at $(0, −7)$ is rotated $90°$ counterclockwise about the origin. What is its new location?","answer":"$(7, 0)$","solution":"Using $(x, y) \\to (−y, x)$: $(0, −7) \\to (7, 0)$."},{"type":"word","q":"A compass needle at $(3, 4)$ is rotated $270°$ counterclockwise. Where does it point?","answer":"$(4, −3)$","solution":"A $270°$ CCW rotation maps $(x, y) \\to (y, −x)$: $(3, 4) \\to (4, −3)$."}]);
  add("geometry", "g3", 2, [{"type":"regular","q":"Dilate the point $(1, 2)$ by scale factor $3$ about the origin.","answer":"$(3, 6)$","solution":"Multiply each coordinate by the scale factor: $(1 \\cdot 3, 2 \\cdot 3) = (3, 6)$."},{"type":"regular","q":"Dilate $(4, −3)$ by scale factor $2$ about the origin.","answer":"$(8, −6)$","solution":"Multiply each coordinate by 2: $(4 \\cdot 2, −3 \\cdot 2) = (8, −6)$."},{"type":"regular","q":"Dilate $(−5, 4)$ by scale factor $\\frac{1}{2}$ about the origin.","answer":"$(−2.5, 2)$","solution":"Multiply each coordinate by $\\frac{1}{2}$: $(−5 \\cdot \\frac{1}{2}, 4 \\cdot \\frac{1}{2}) = (−2.5, 2)$."},{"type":"regular","q":"Dilate $(3, 3)$ by scale factor $4$ about the origin.","answer":"$(12, 12)$","solution":"Multiply each coordinate by 4: $(3 \\cdot 4, 3 \\cdot 4) = (12, 12)$."},{"type":"regular","q":"Dilate $(−2, −6)$ by scale factor $\\frac{1}{3}$ about the origin.","answer":"$(−\\frac{2}{3}, −2)$","solution":"Multiply each coordinate by $\\frac{1}{3}$: $(−2 \\cdot \\frac{1}{3}, −6 \\cdot \\frac{1}{3}) = (−\\frac{2}{3}, −2)$."},{"type":"regular","q":"Dilate $(7, 0)$ by scale factor $5$ about the origin.","answer":"$(35, 0)$","solution":"Multiply each coordinate by 5: $(7 \\cdot 5, 0 \\cdot 5) = (35, 0)$."},{"type":"regular","q":"Dilate $(0, 8)$ by scale factor $\\frac{1}{4}$ about the origin.","answer":"$(0, 2)$","solution":"Multiply each coordinate by $\\frac{1}{4}$: $(0 \\cdot \\frac{1}{4}, 8 \\cdot \\frac{1}{4}) = (0, 2)$."},{"type":"regular","q":"Dilate $(−4, 5)$ by scale factor $2.5$ about the origin.","answer":"$(−10, 12.5)$","solution":"Multiply each coordinate by 2.5: $(−4 \\cdot 2.5, 5 \\cdot 2.5) = (−10, 12.5)$."},{"type":"regular","q":"Dilate $(9, −3)$ by scale factor $\\frac{1}{3}$ about the origin.","answer":"$(3, −1)$","solution":"Multiply each coordinate by $\\frac{1}{3}$: $(9 \\cdot \\frac{1}{3}, −3 \\cdot \\frac{1}{3}) = (3, −1)$."},{"type":"word","q":"A rectangle with vertices at $(1, 1)$, $(1, 3)$, $(4, 3)$, and $(4, 1)$ is dilated by scale factor $2$. What is one vertex's new position?","answer":"$(2, 2)$ (or $(2, 6)$, $(8, 6)$, $(8, 2)$)","solution":"Multiply each coordinate by 2; for example, $(1, 1) \\to (2, 2)$."},{"type":"word","q":"A triangle has a side of length 10 cm. After dilation by scale factor $\\frac{1}{5}$, what is the new side length?","answer":"2 cm","solution":"Multiply the original length by the scale factor: $10 \\cdot \\frac{1}{5} = 2$ cm."},{"type":"word","q":"A blueprint point at $(6, 8)$ represents a location on a building. If the scale factor is $10$, what are the actual coordinates?","answer":"$(60, 80)$","solution":"Multiply each coordinate by 10: $(6 \\cdot 10, 8 \\cdot 10) = (60, 80)$."},{"type":"word","q":"A square has side length 20 units. After dilation by scale factor $0.5$, what is the new side length?","answer":"10 units","solution":"Multiply the original side length by 0.5: $20 \\cdot 0.5 = 10$ units."},{"type":"word","q":"A circle with radius 6 units is dilated by scale factor $3$. What is the new radius?","answer":"18 units","solution":"Multiply the original radius by the scale factor: $6 \\cdot 3 = 18$ units."},{"type":"word","q":"A map point at $(−4, 2)$ is enlarged by scale factor $2.5$. What are the new coordinates?","answer":"$(−10, 5)$","solution":"Multiply each coordinate by 2.5: $(−4 \\cdot 2.5, 2 \\cdot 2.5) = (−10, 5)$."}]);
