  add("geometry", "g4", 0, [{"type":"regular","q":"A triangle has sides 5 cm, 5 cm, and 8 cm. Classify it by sides.","answer":"Isosceles","solution":"Two sides are equal (5 cm and 5 cm), making it isosceles."},{"type":"regular","q":"A triangle has angles 120°, 35°, and 25°. Classify it by angles.","answer":"Obtuse","solution":"One angle (120°) is greater than 90°, so it is obtuse."},{"type":"regular","q":"A triangle has all angles less than 90°. What type is it?","answer":"Acute","solution":"All angles are less than 90°, which defines an acute triangle."},{"type":"regular","q":"A triangle has sides 3, 4, and 5. Classify it by sides.","answer":"Scalene","solution":"All three sides have different lengths, making it scalene."},{"type":"regular","q":"A right triangle has two sides of equal length. What is it called?","answer":"Right isosceles","solution":"It has a right angle and two equal sides, so it is right isosceles."},{"type":"regular","q":"Can a triangle be both right and equilateral?","answer":"No","solution":"An equilateral triangle has all 60° angles, so it cannot have a 90° angle."},{"type":"regular","q":"A triangle has angles 50°, 50°, and 80°. Classify by angles and sides.","answer":"Acute isosceles","solution":"All angles are less than 90° (acute) and two angles are equal (isosceles)."},{"type":"word","q":"A triangular garden has sides 10 m, 10 m, and 12 m. What type of triangle is it?","answer":"Isosceles","solution":"Two sides are equal (10 m each), making it isosceles."},{"type":"word","q":"A roof truss forms a triangle with angles 90°, 50°, and 40°. Classify it.","answer":"Right","solution":"One angle is 90°, so it is a right triangle."},{"type":"word","q":"A triangular sail has all three sides measuring 6 feet. What type is it?","answer":"Equilateral","solution":"All three sides are equal, making it equilateral."},{"type":"word","q":"A triangle has angles 65°, 65°, and 50°. Is it acute or obtuse?","answer":"Acute","solution":"All angles are less than 90°, making it acute."},{"type":"word","q":"A decorative triangle has sides 7 cm, 8 cm, and 9 cm. Classify by sides.","answer":"Scalene","solution":"All three sides have different lengths, making it scalene."},{"type":"regular","q":"A triangle has one angle of 95°. What type is it by angles?","answer":"Obtuse","solution":"One angle exceeds 90°, defining an obtuse triangle."},{"type":"regular","q":"Two sides of a triangle are 6 inches each. The third is 10 inches. Classify by sides.","answer":"Isosceles","solution":"Two sides are equal (6 inches), making it isosceles."},{"type":"word","q":"A triangular warning sign has angles 60°, 60°, and 60°. What type is it?","answer":"Equilateral","solution":"All three angles are equal, and all sides are equal, making it equilateral."}]);
  add("geometry", "g4", 1, [{"type":"regular","q":"Triangle ABC has AB = 5, BC = 7, CA = 6. Triangle DEF has DE = 5, EF = 7, FD = 6. By which postulate are they congruent?","answer":"SSS","solution":"All three pairs of corresponding sides are equal, so SSS applies."},{"type":"regular","q":"In triangles PQR and STU, angle P = angle S, side PQ = ST, and angle Q = angle T. Which postulate proves congruence?","answer":"ASA","solution":"Two angles and the included side are congruent, so ASA applies."},{"type":"regular","q":"Triangle ABC has angle A = 45°, side AB = 8, and angle B = 60°. Triangle XYZ has angle X = 45°, side XY = 8, and angle Y = 60°. Congruent by?","answer":"ASA","solution":"Two angles and the included side match, so ASA proves congruence."},{"type":"regular","q":"Triangles have angle 30°, side 5 cm, and angle 70° in the same order. Are they congruent? By which postulate?","answer":"Yes, ASA","solution":"Two angles with the included side between them match, so ASA applies."},{"type":"regular","q":"Triangle MNO has MN = 9, angle N = 50°, and NO = 12. Triangle PQR has PQ = 9, angle Q = 50°, and QR = 12. Congruent by?","answer":"SAS","solution":"Two sides and the included angle are congruent, so SAS applies."},{"type":"regular","q":"Can two triangles with all three angles equal be non-congruent?","answer":"Yes","solution":"AAA only proves similarity, not congruence; triangles can have the same angles but different sizes."},{"type":"regular","q":"Triangle ABC has angle A = 35°, angle B = 75°, and side BC = 10. Triangle DEF has angle D = 35°, angle E = 75°, and side EF = 10. Congruent by?","answer":"AAS","solution":"Two angles and a non-included side are congruent, so AAS applies."},{"type":"word","q":"Two triangular picture frames have three sides measuring 12 in, 15 in, and 18 in each. By which postulate are they congruent?","answer":"SSS","solution":"All three pairs of sides are equal, so SSS proves congruence."},{"type":"word","q":"Two triangular tiles have a 40° angle, a 10 cm side adjacent to it, and another 50° angle. Are they congruent? By what postulate?","answer":"Yes, ASA","solution":"Two angles and the included side match, so ASA proves congruence."},{"type":"word","q":"A surveyor measures two triangular plots: each has sides 50 m and 60 m with a 35° included angle. By which postulate are they congruent?","answer":"SAS","solution":"Two sides and the included angle are equal, so SAS applies."},{"type":"word","q":"Two triangular sails have angles 55° and 65° with a non-included side of 8 feet. Are they congruent? By which postulate?","answer":"Yes, AAS","solution":"Two angles and a non-included side are congruent, so AAS applies."},{"type":"word","q":"Two triangular patches have all three angles 50°, 60°, and 70°. Can you prove they are congruent?","answer":"No","solution":"AAA only proves similarity, not congruence; they could be different sizes."},{"type":"regular","q":"Triangle JKL has JK = 7, KL = 5, and angle K = 40°. Triangle MNO has MN = 7, NO = 5, and angle N = 40°. Congruent by?","answer":"SAS","solution":"Two sides and the included angle are congruent, so SAS applies."},{"type":"regular","q":"Two triangles have angle 28°, angle 92°, and side 6 inches (non-included). Congruent by?","answer":"AAS","solution":"Two angles and a non-included side match, so AAS proves congruence."},{"type":"word","q":"A carpenter has two triangular braces with sides 3 ft, 4 ft, and 5 ft. By which postulate are they congruent?","answer":"SSS","solution":"All three sides are equal, so SSS proves congruence."}]);
  add("geometry", "g4", 2, [{"type":"regular","q":"An isosceles triangle has a vertex angle of 50°. Find each base angle.","answer":"65°","solution":"Base angles are equal; (180° − 50°) ÷ 2 = 65°."},{"type":"regular","q":"An isosceles triangle has base angles of 55° each. Find the vertex angle.","answer":"70°","solution":"Vertex angle = 180° − 55° − 55° = 70°."},{"type":"regular","q":"An equilateral triangle has a side length of 9 cm. What is its perimeter?","answer":"27 cm","solution":"All three sides are equal; 3 × 9 = 27 cm."},{"type":"regular","q":"In an isosceles triangle, the vertex angle is 100°. What are the base angles?","answer":"40° each","solution":"Base angles are equal; (180° − 100°) ÷ 2 = 40°."},{"type":"regular","q":"An isosceles triangle has two sides of 8 inches and a base of 6 inches. What is the perimeter?","answer":"22 inches","solution":"Perimeter = 8 + 8 + 6 = 22 inches."},{"type":"regular","q":"An equilateral triangle has a perimeter of 36 cm. What is each side length?","answer":"12 cm","solution":"Each side = 36 ÷ 3 = 12 cm."},{"type":"regular","q":"An isosceles triangle has base angles of 62° each. Find the vertex angle.","answer":"56°","solution":"Vertex angle = 180° − 62° − 62° = 56°."},{"type":"regular","q":"In an isosceles triangle, each base angle is 48°. What is the vertex angle?","answer":"84°","solution":"Vertex angle = 180° − 48° − 48° = 84°."},{"type":"word","q":"A triangular roof has two equal sides of 20 feet and base angles of 70° each. Find the vertex angle.","answer":"40°","solution":"Vertex angle = 180° − 70° − 70° = 40°."},{"type":"word","q":"An isosceles pennant has a vertex angle of 60°. What is each base angle?","answer":"60°","solution":"(180° − 60°) ÷ 2 = 60°; this makes it equilateral."},{"type":"word","q":"A triangular park is equilateral with sides of 150 meters. What is the perimeter?","answer":"450 meters","solution":"Perimeter = 3 × 150 = 450 meters."},{"type":"word","q":"An isosceles triangle has a vertex angle of 110° and two equal sides of 5 cm. Find each base angle.","answer":"35°","solution":"(180° − 110°) ÷ 2 = 35°."},{"type":"word","q":"A triangular flag is isosceles with base angles of 58° each. What is the vertex angle?","answer":"64°","solution":"Vertex angle = 180° − 58° − 58° = 64°."},{"type":"regular","q":"An equilateral triangle has each angle measuring 60°. If one side is 15 cm, what is the perimeter?","answer":"45 cm","solution":"All sides are equal; perimeter = 3 × 15 = 45 cm."},{"type":"word","q":"An isosceles triangle has two sides of 13 inches and a base of 10 inches. What is the perimeter?","answer":"36 inches","solution":"Perimeter = 13 + 13 + 10 = 36 inches."}]);
  addCum("geometry", "g4", [{"type":"regular","q":"A triangle has angles 30°, 60°, and 90°. Classify it by angles and sides.","answer":"Right scalene","solution":"It has a 90° angle (right) and all different side lengths (scalene)."},{"type":"regular","q":"Two triangles have all three sides congruent. By which postulate are they congruent?","answer":"SSS","solution":"Three pairs of congruent sides prove congruence by SSS."},{"type":"regular","q":"An isosceles triangle has a vertex angle of 36°. Find each base angle.","answer":"72°","solution":"Base angles are equal; (180° − 36°) ÷ 2 = 72°."},{"type":"regular","q":"A triangle has angles 75°, 75°, and 30°. Classify by angles and sides.","answer":"Acute isosceles","solution":"All angles are less than 90° (acute) and two angles are equal (isosceles)."},{"type":"regular","q":"Two triangles have angle 50°, side 6 cm, angle 70°, and non-included side. Congruent by?","answer":"AAS","solution":"Two angles and a non-included side are congruent, so AAS applies."},{"type":"regular","q":"An equilateral triangle has a perimeter of 24 inches. What is each side?","answer":"8 inches","solution":"Each side = 24 ÷ 3 = 8 inches."},{"type":"regular","q":"Two triangles have sides 4, 5, 6 and 4, 5, 6. Congruent by?","answer":"SSS","solution":"All three pairs of sides are equal, so SSS proves congruence."},{"type":"regular","q":"A triangle has two angles of 45° each. What is the third angle?","answer":"90°","solution":"Third angle = 180° − 45° − 45° = 90°."},{"type":"regular","q":"An isosceles triangle has base angles of 68° each. Find the vertex angle.","answer":"44°","solution":"Vertex angle = 180° − 68° − 68° = 44°."},{"type":"regular","q":"Two triangles have two sides 7 and 9 with a 35° included angle. Congruent by?","answer":"SAS","solution":"Two sides and the included angle are congruent, so SAS applies."},{"type":"word","q":"A triangular garden plot has sides 8 m, 8 m, and 10 m. Classify by sides.","answer":"Isosceles","solution":"Two sides are equal (8 m each), making it isosceles."},{"type":"word","q":"Two triangular roof sections have angles 40°, 70°, 70° and sides 12 ft, 12 ft, 15 ft. Classify the first by angles.","answer":"Acute isosceles","solution":"All angles are less than 90° (acute) and two angles are equal (isosceles)."},{"type":"word","q":"A surveyor measures two triangular plots with sides 50 m, 60 m, 70 m each. By which postulate are they congruent?","answer":"SSS","solution":"All three pairs of sides are equal, so SSS proves congruence."},{"type":"word","q":"Two triangular tiles have angles 45°, 45°, 90° and sides 5 in, 5 in, 7 in. What type is each?","answer":"Right isosceles","solution":"Each has a 90° angle and two equal sides, making it right isosceles."},{"type":"word","q":"A triangular sail has angles 60°, 60°, 60° and perimeter 18 feet. What is each side?","answer":"6 feet","solution":"It is equilateral; each side = 18 ÷ 3 = 6 feet."},{"type":"word","q":"Two triangular patches have angle 55°, side 8 cm, angle 65°, and non-included side. Congruent by?","answer":"AAS","solution":"Two angles and a non-included side are congruent, so AAS applies."},{"type":"word","q":"A triangular warning sign has all sides equal to 12 inches. What is the perimeter?","answer":"36 inches","solution":"Perimeter = 3 × 12 = 36 inches."},{"type":"word","q":"An isosceles triangle has vertex angle 80° and two equal sides of 9 cm. Find each base angle.","answer":"50°","solution":"(180° − 80°) ÷ 2 = 50°."},{"type":"word","q":"Two triangular braces have sides 3 ft, 4 ft, 5 ft and 3 ft, 4 ft, 5 ft. Congruent by?","answer":"SSS","solution":"All three pairs of sides are equal, so SSS proves congruence."},{"type":"word","q":"A triangular park has angles 50°, 60°, 70°. Classify it by angles.","answer":"Acute","solution":"All angles are less than 90°, making it acute."},{"type":"word","q":"Two triangular roof trusses have a 40° angle, 15 ft side, and 50° angle in order. Congruent by?","answer":"ASA","solution":"Two angles and the included side are congruent, so ASA applies."},{"type":"word","q":"An isosceles triangle has a base of 14 cm and two equal sides of 10 cm each. What is the perimeter?","answer":"34 cm","solution":"Perimeter = 10 + 10 + 14 = 34 cm."},{"type":"word","q":"A triangular banner has angles 30°, 30°, 120°. What type is it?","answer":"Obtuse isosceles","solution":"One angle exceeds 90° (obtuse) and two angles are equal (isosceles)."},{"type":"word","q":"Two triangular tiles have sides 6 in, 8 in, 10 in and sides 6 in, 8 in, 10 in. By which postulate are they congruent?","answer":"SSS","solution":"All three pairs of sides are equal, so SSS proves congruence."},{"type":"word","q":"An equilateral triangle has each angle 60°. If the perimeter is 30 cm, what is each side?","answer":"10 cm","solution":"Each side = 30 ÷ 3 = 10 cm."}]);
  add("geometry", "g5", 0, [{"type":"regular","q":"What is the sum of interior angles of a nonagon (9-sided polygon)?","answer":"\\(1260°\\)","solution":"Use the formula \\((n-2) \\times 180°\\) where \\(n=9\\): \\((9-2) \\times 180° = 7 \\times 180° = 1260°\\)."},{"type":"regular","q":"A regular polygon has each interior angle equal to \\(144°\\). How many sides does it have?","answer":"10","solution":"Each interior angle of a regular \\(n\\)-gon is \\(\\frac{(n-2) \\times 180°}{n}\\); solve \\(\\frac{(n-2) \\times 180°}{n} = 144°\\) to get \\(n=10\\)."},{"type":"regular","q":"What is each exterior angle of a regular 9-sided polygon?","answer":"\\(40°\\)","solution":"The sum of exterior angles is always \\(360°\\), so each angle in a regular 9-gon is \\(360° \\div 9 = 40°\\)."},{"type":"regular","q":"A regular polygon has each exterior angle equal to \\(18°\\). How many sides?","answer":"20","solution":"Number of sides \\(= 360° \\div 18° = 20\\)."},{"type":"regular","q":"Find the sum of interior angles of a 15-sided polygon.","answer":"\\(2340°\\)","solution":"\\((15-2) \\times 180° = 13 \\times 180° = 2340°\\)."},{"type":"regular","q":"Each interior angle of a regular polygon is \\(165°\\). How many sides?","answer":"24","solution":"Solve \\(\\frac{(n-2) \\times 180°}{n} = 165°\\) to get \\(n=24\\)."},{"type":"regular","q":"What is each interior angle of a regular 20-gon?","answer":"\\(162°\\)","solution":"\\(\\frac{(20-2) \\times 180°}{20} = \\frac{18 \\times 180°}{20} = \\frac{3240°}{20} = 162°\\)."},{"type":"regular","q":"A regular polygon has each exterior angle of \\(24°\\). How many sides?","answer":"15","solution":"Number of sides \\(= 360° \\div 24° = 15\\)."},{"type":"regular","q":"Find the sum of interior angles of a 12-sided polygon.","answer":"\\(1800°\\)","solution":"\\((12-2) \\times 180° = 10 \\times 180° = 1800°\\)."},{"type":"word","q":"A decorative tile is shaped like a regular hexagon. What is the measure of each interior angle?","answer":"\\(120°\\)","solution":"\\(\\frac{(6-2) \\times 180°}{6} = \\frac{720°}{6} = 120°\\)."},{"type":"word","q":"An architect designs a regular polygon-shaped room where each interior angle is \\(135°\\). How many sides does the room have?","answer":"8","solution":"Solve \\(\\frac{(n-2) \\times 180°}{n} = 135°\\) to get \\(n=8\\)."},{"type":"word","q":"A stop sign is shaped like a regular octagon. What is each exterior angle?","answer":"\\(45°\\)","solution":"\\(360° \\div 8 = 45°\\)."},{"type":"word","q":"A regular polygon has 18 sides. What is the sum of all its interior angles?","answer":"\\(2880°\\)","solution":"\\((18-2) \\times 180° = 16 \\times 180° = 2880°\\)."},{"type":"word","q":"A garden is designed as a regular polygon where each exterior angle is \\(30°\\). How many sides does the garden have?","answer":"12","solution":"Number of sides \\(= 360° \\div 30° = 12\\)."},{"type":"word","q":"A regular polygon has each interior angle of \\(156°\\). How many sides does it have?","answer":"15","solution":"Solve \\(\\frac{(n-2) \\times 180°}{n} = 156°\\) to get \\(n=15\\)."}]);
  add("geometry", "g5", 1, [{"type":"regular","q":"In parallelogram \\(MNOP\\), \\(\\angle M = 55°\\). Find \\(\\angle O\\).","answer":"\\(55°\\)","solution":"Opposite angles in a parallelogram are congruent, so \\(\\angle O = \\angle M = 55°\\)."},{"type":"regular","q":"In parallelogram \\(ABCD\\), \\(\\angle B = 120°\\). Find \\(\\angle D\\).","answer":"\\(120°\\)","solution":"Opposite angles in a parallelogram are equal, so \\(\\angle D = \\angle B = 120°\\)."},{"type":"regular","q":"In parallelogram \\(EFGH\\), \\(\\angle E = 75°\\). Find \\(\\angle F\\).","answer":"\\(105°\\)","solution":"Consecutive angles in a parallelogram are supplementary, so \\(\\angle F = 180° - 75° = 105°\\)."},{"type":"regular","q":"In parallelogram \\(JKLM\\), side \\(JK = 15\\) cm. What is the length of side \\(ML\\)?","answer":"15 cm","solution":"Opposite sides of a parallelogram are congruent, so \\(ML = JK = 15\\) cm."},{"type":"regular","q":"In parallelogram \\(QRST\\), \\(QR = 9\\) cm and \\(RS = 6\\) cm. Find the perimeter.","answer":"30 cm","solution":"Opposite sides are equal, so perimeter \\(= 2(9 + 6) = 2(15) = 30\\) cm."},{"type":"regular","q":"In parallelogram \\(UVWX\\), diagonal \\(UW\\) and diagonal \\(VX\\) intersect at point \\(Y\\). If \\(UY = 7\\) cm, find \\(YW\\).","answer":"7 cm","solution":"Diagonals of a parallelogram bisect each other, so \\(YW = UY = 7\\) cm."},{"type":"regular","q":"In parallelogram \\(BCDE\\), \\(\\angle C = 68°\\). Find \\(\\angle B\\).","answer":"\\(112°\\)","solution":"Consecutive angles are supplementary, so \\(\\angle B = 180° - 68° = 112°\\)."},{"type":"regular","q":"In parallelogram \\(FGHI\\), side \\(FG = 11\\) cm. What is side \\(HI\\)?","answer":"11 cm","solution":"Opposite sides of a parallelogram are congruent."},{"type":"regular","q":"In parallelogram \\(KLMN\\), if \\(\\angle K = 42°\\), find \\(\\angle L\\).","answer":"\\(138°\\)","solution":"Consecutive angles sum to \\(180°\\), so \\(\\angle L = 180° - 42° = 138°\\)."},{"type":"word","q":"A parallelogram-shaped garden has one side measuring 20 meters. What is the length of the opposite side?","answer":"20 meters","solution":"Opposite sides of a parallelogram are equal in length."},{"type":"word","q":"In a parallelogram-shaped window frame, one corner angle is \\(65°\\). What is the angle at the adjacent corner?","answer":"\\(115°\\)","solution":"Consecutive angles in a parallelogram are supplementary: \\(180° - 65° = 115°\\)."},{"type":"word","q":"A parallelogram has sides of 8 cm and 5 cm. What is its perimeter?","answer":"26 cm","solution":"Perimeter \\(= 2(8 + 5) = 2(13) = 26\\) cm."},{"type":"word","q":"In a parallelogram, the diagonals intersect at point \\(O\\). If one segment from a vertex to \\(O\\) is 6 cm, what is the length of the opposite segment?","answer":"6 cm","solution":"Diagonals bisect each other, so opposite segments are equal."},{"type":"word","q":"A parallelogram-shaped field has one angle of \\(58°\\). What is the measure of the angle opposite to it?","answer":"\\(58°\\)","solution":"Opposite angles in a parallelogram are congruent."},{"type":"word","q":"In a parallelogram \\(PQRS\\), if \\(\\angle P = 78°\\) and \\(\\angle Q = 102°\\), verify the parallelogram property and find \\(\\angle S\\).","answer":"\\(78°\\)","solution":"Opposite angles are equal, so \\(\\angle S = \\angle P = 78°\\); also, \\(\\angle P + \\angle Q = 78° + 102° = 180°\\) confirms consecutive angles are supplementary."}]);
  add("geometry", "g5", 2, [{"type":"regular","q":"A rhombus has a side length of 9 cm. What is its perimeter?","answer":"36 cm","solution":"All sides of a rhombus are equal, so perimeter \\(= 4 \\times 9 = 36\\) cm."},{"type":"regular","q":"A rectangle has a length of 12 cm and width of 5 cm. What is the length of its diagonals?","answer":"13 cm","solution":"Use the Pythagorean theorem: \\(d = \\sqrt{12^2 + 5^2} = \\sqrt{144 + 25} = \\sqrt{169} = 13\\) cm."},{"type":"regular","q":"A square has a side length of 8 cm. What is the length of its diagonal?","answer":"\\(8\\sqrt{2}\\) cm","solution":"In a square with side \\(s\\), the diagonal is \\(s\\sqrt{2}\\), so \\(8\\sqrt{2}\\) cm."},{"type":"regular","q":"A trapezoid has bases of 7 cm and 13 cm. What is the length of the midsegment?","answer":"10 cm","solution":"Midsegment \\(= \\frac{b_1 + b_2}{2} = \\frac{7 + 13}{2} = \\frac{20}{2} = 10\\) cm."},{"type":"regular","q":"A rhombus has diagonals of length 10 cm and 24 cm. What is the length of each side?","answer":"13 cm","solution":"The diagonals bisect each other at right angles; half-diagonals are 5 cm and 12 cm; side \\(= \\sqrt{5^2 + 12^2} = \\sqrt{25 + 144} = \\sqrt{169} = 13\\) cm."},{"type":"regular","q":"A rectangle has diagonals of 20 cm. If one side is 12 cm, what is the other side?","answer":"16 cm","solution":"Use the Pythagorean theorem: \\(12^2 + x^2 = 20^2\\), so \\(144 + x^2 = 400\\), giving \\(x = 16\\) cm."},{"type":"regular","q":"A square has a perimeter of 40 cm. What is the length of its diagonal?","answer":"\\(10\\sqrt{2}\\) cm","solution":"Side \\(= 40 \\div 4 = 10\\) cm; diagonal \\(= 10\\sqrt{2}\\) cm."},{"type":"regular","q":"A trapezoid has bases of 9 cm and 15 cm, and both legs are 5 cm. What is the midsegment?","answer":"12 cm","solution":"Midsegment \\(= \\frac{9 + 15}{2} = \\frac{24}{2} = 12\\) cm."},{"type":"regular","q":"In a rhombus, the diagonals are 16 cm and 12 cm. What is the side length?","answer":"10 cm","solution":"Half-diagonals are 8 cm and 6 cm; side \\(= \\sqrt{8^2 + 6^2} = \\sqrt{64 + 36} = \\sqrt{100} = 10\\) cm."},{"type":"word","q":"A square tile has a side length of 6 inches. What is the length of the diagonal?","answer":"\\(6\\sqrt{2}\\) inches","solution":"Diagonal of a square with side \\(s\\) is \\(s\\sqrt{2}\\), so \\(6\\sqrt{2}\\) inches."},{"type":"word","q":"A rectangular swimming pool is 30 meters long and 16 meters wide. What is the diagonal distance across the pool?","answer":"34 meters","solution":"\\(d = \\sqrt{30^2 + 16^2} = \\sqrt{900 + 256} = \\sqrt{1156} = 34\\) meters."},{"type":"word","q":"A rhombus-shaped garden has a perimeter of 52 meters. What is the length of each side?","answer":"13 meters","solution":"All sides are equal; side \\(= 52 \\div 4 = 13\\) meters."},{"type":"word","q":"A trapezoid-shaped roof section has parallel sides of 8 feet and 20 feet. What is the length of the midsegment?","answer":"14 feet","solution":"Midsegment \\(= \\frac{8 + 20}{2} = \\frac{28}{2} = 14\\) feet."},{"type":"word","q":"A rectangular frame has a diagonal of 25 cm and one side of 7 cm. What is the length of the other side?","answer":"24 cm","solution":"\\(7^2 + x^2 = 25^2\\), so \\(49 + x^2 = 625\\), giving \\(x = 24\\) cm."},{"type":"word","q":"A rhombus has diagonals of 20 cm and 48 cm. What is the perimeter?","answer":"104 cm","solution":"Half-diagonals are 10 cm and 24 cm; side \\(= \\sqrt{10^2 + 24^2} = \\sqrt{100 + 576} = \\sqrt{676} = 26\\) cm; perimeter \\(= 4 \\times 26 = 104\\) cm."}]);
  addCum("geometry", "g5", [{"type":"regular","q":"What is the sum of interior angles of a 13-sided polygon?","answer":"\\(1980°\\)","solution":"\\((13-2) \\times 180° = 11 \\times 180° = 1980°\\)."},{"type":"regular","q":"Each exterior angle of a regular 16-gon is?","answer":"\\(22.5°\\)","solution":"\\(360° \\div 16 = 22.5°\\)."},{"type":"regular","q":"A regular polygon has each interior angle of \\(140°\\). How many sides?","answer":"9","solution":"Solve \\(\\frac{(n-2) \\times 180°}{n} = 140°\\) to get \\(n=9\\)."},{"type":"regular","q":"In parallelogram \\(ABCD\\), \\(\\angle A = 48°\\). Find \\(\\angle B\\).","answer":"\\(132°\\)","solution":"Consecutive angles are supplementary: \\(180° - 48° = 132°\\)."},{"type":"regular","q":"In parallelogram \\(EFGH\\), \\(EF = 14\\) cm and \\(FG = 9\\) cm. What is the perimeter?","answer":"46 cm","solution":"Perimeter \\(= 2(14 + 9) = 2(23) = 46\\) cm."},{"type":"regular","q":"A rectangle has dimensions 9 cm by 12 cm. What is the length of its diagonal?","answer":"15 cm","solution":"\\(d = \\sqrt{9^2 + 12^2} = \\sqrt{81 + 144} = \\sqrt{225} = 15\\) cm."},{"type":"regular","q":"A square has a side of 5 cm. What is its diagonal?","answer":"\\(5\\sqrt{2}\\) cm","solution":"Diagonal \\(= 5\\sqrt{2}\\) cm."},{"type":"regular","q":"A trapezoid has bases 11 cm and 19 cm. What is the midsegment?","answer":"15 cm","solution":"Midsegment \\(= \\frac{11 + 19}{2} = 15\\) cm."},{"type":"regular","q":"A rhombus has a perimeter of 48 cm. What is each side?","answer":"12 cm","solution":"Side \\(= 48 \\div 4 = 12\\) cm."},{"type":"regular","q":"In parallelogram \\(PQRS\\), diagonal \\(PR\\) intersects diagonal \\(QS\\) at \\(O\\). If \\(PO = 8\\) cm, find \\(OR\\).","answer":"8 cm","solution":"Diagonals bisect each other, so \\(OR = PO = 8\\) cm."},{"type":"regular","q":"A regular 11-gon has an interior angle sum of?","answer":"\\(1620°\\)","solution":"\\((11-2) \\times 180° = 9 \\times 180° = 1620°\\)."},{"type":"regular","q":"A rhombus has diagonals of 14 cm and 48 cm. What is the side length?","answer":"25 cm","solution":"Half-diagonals are 7 cm and 24 cm; side \\(= \\sqrt{7^2 + 24^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25\\) cm."},{"type":"word","q":"A regular polygon has each exterior angle of \\(20°\\). How many sides does it have?","answer":"18","solution":"Number of sides \\(= 360° \\div 20° = 18\\)."},{"type":"word","q":"A parallelogram-shaped piece of fabric has one angle of \\(72°\\). What is the angle adjacent to it?","answer":"\\(108°\\)","solution":"Consecutive angles sum to \\(180°\\): \\(180° - 72° = 108°\\)."},{"type":"word","q":"A rectangular garden is 20 meters by 21 meters. What is the diagonal distance?","answer":"29 meters","solution":"\\(d = \\sqrt{20^2 + 21^2} = \\sqrt{400 + 441} = \\sqrt{841} = 29\\) meters."},{"type":"word","q":"A trapezoid-shaped table has parallel sides of 3 feet and 7 feet. What is the midsegment length?","answer":"5 feet","solution":"Midsegment \\(= \\frac{3 + 7}{2} = 5\\) feet."},{"type":"word","q":"A rhombus-shaped sign has a perimeter of 60 inches. What is the length of one side?","answer":"15 inches","solution":"Side \\(= 60 \\div 4 = 15\\) inches."},{"type":"word","q":"An architect designs a regular 14-sided building. What is the sum of all interior angles?","answer":"\\(2160°\\)","solution":"\\((14-2) \\times 180° = 12 \\times 180° = 2160°\\)."},{"type":"word","q":"In a parallelogram, opposite sides are always what?","answer":"Equal in length","solution":"This is a fundamental property of parallelograms."},{"type":"word","q":"A square picture frame has a side of 10 inches. What is the diagonal?","answer":"\\(10\\sqrt{2}\\) inches","solution":"Diagonal \\(= 10\\sqrt{2}\\) inches."},{"type":"word","q":"A rectangular pool has a diagonal of 26 meters and one side of 10 meters. What is the other side?","answer":"24 meters","solution":"\\(10^2 + x^2 = 26^2\\), so \\(100 + x^2 = 676\\), giving \\(x = 24\\) meters."},{"type":"word","q":"A trapezoid has bases of 5 cm and 17 cm and legs of 6 cm each. What is the midsegment?","answer":"11 cm","solution":"Midsegment \\(= \\frac{5 + 17}{2} = 11\\) cm."},{"type":"word","q":"A rhombus has diagonals of 30 cm and 16 cm. What is the perimeter?","answer":"68 cm","solution":"Half-diagonals are 15 cm and 8 cm; side \\(= \\sqrt{15^2 + 8^2} = \\sqrt{225 + 64} = \\sqrt{289} = 17\\) cm; perimeter \\(= 4 \\times 17 = 68\\) cm."},{"type":"word","q":"In a parallelogram, if one angle is \\(85°\\), what is the opposite angle?","answer":"\\(85°\\)","solution":"Opposite angles in a parallelogram are congruent."}]);
  add("geometry", "g6", 0, [{"type":"regular","q":"Solve: \\(\\dfrac{7}{11} = \\dfrac{x}{33}\\).","answer":"\\(x = 21\\)","solution":"Cross-multiply: \\(7 \\times 33 = 11x\\), so \\(231 = 11x\\), giving \\(x = 21\\)."},{"type":"regular","q":"Simplify the ratio \\(36 : 48\\).","answer":"\\(3 : 4\\)","solution":"Divide both by their GCD of 12."},{"type":"regular","q":"Solve: \\(\\dfrac{15}{x} = \\dfrac{5}{4}\\).","answer":"\\(x = 12\\)","solution":"Cross-multiply: \\(15 \\times 4 = 5x\\), so \\(60 = 5x\\), giving \\(x = 12\\)."},{"type":"regular","q":"Simplify the ratio \\(28 : 42\\).","answer":"\\(2 : 3\\)","solution":"Divide both by their GCD of 14."},{"type":"regular","q":"Solve: \\(\\dfrac{x}{16} = \\dfrac{5}{8}\\).","answer":"\\(x = 10\\)","solution":"Cross-multiply: \\(8x = 80\\), so \\(x = 10\\)."},{"type":"regular","q":"Simplify the ratio \\(54 : 81\\).","answer":"\\(2 : 3\\)","solution":"Divide both by their GCD of 27."},{"type":"regular","q":"Solve: \\(\\dfrac{6}{x} = \\dfrac{9}{15}\\).","answer":"\\(x = 10\\)","solution":"Cross-multiply: \\(6 \\times 15 = 9x\\), so \\(90 = 9x\\), giving \\(x = 10\\)."},{"type":"regular","q":"Simplify the ratio \\(32 : 40\\).","answer":"\\(4 : 5\\)","solution":"Divide both by their GCD of 8."},{"type":"regular","q":"Solve: \\(\\dfrac{x}{25} = \\dfrac{4}{5}\\).","answer":"\\(x = 20\\)","solution":"Cross-multiply: \\(5x = 100\\), so \\(x = 20\\)."},{"type":"word","q":"A paint mixture uses 5 parts blue for every 7 parts white. How much blue is needed for 35 parts white?","answer":"25 parts","solution":"Set up the proportion \\(\\dfrac{5}{7} = \\dfrac{x}{35}\\); cross-multiply to get \\(x = 25\\)."},{"type":"word","q":"A blueprint scale is 1 cm = 2 m. What distance does 4.5 cm represent?","answer":"9 m","solution":"Multiply 4.5 by 2 to get 9 m."},{"type":"word","q":"A juice recipe calls for 3 parts orange juice to 2 parts lemon juice. How much lemon juice is needed for 15 parts orange juice?","answer":"10 parts","solution":"Set up \\(\\dfrac{3}{2} = \\dfrac{15}{x}\\); cross-multiply to get \\(x = 10\\)."},{"type":"word","q":"A map scale is 1 in = 75 mi. How many miles do 2.4 in represent?","answer":"180 mi","solution":"Multiply 2.4 by 75 to get 180 mi."},{"type":"word","q":"A concrete mix uses 2 parts cement for every 5 parts sand. How much cement for 30 parts sand?","answer":"12 parts","solution":"Set up \\(\\dfrac{2}{5} = \\dfrac{x}{30}\\); cross-multiply to get \\(x = 12\\)."},{"type":"word","q":"A model car is built to scale 1:64. If the real car is 192 inches long, how long is the model in inches?","answer":"3 inches","solution":"Divide 192 by 64 to get 3 inches."}]);
  add("geometry", "g6", 1, [{"type":"regular","q":"If \\(\\triangle PQR \\sim \\triangle STU\\) and \\(PQ = 8\\), \\(ST = 12\\), what is the scale factor from \\(PQR\\) to \\(STU\\)?","answer":"\\(\\dfrac{3}{2}\\)","solution":"The scale factor is the ratio of corresponding sides: \\(\\dfrac{ST}{PQ} = \\dfrac{12}{8} = \\dfrac{3}{2}\\)."},{"type":"regular","q":"Two triangles have angles \\(45°, 60°, 75°\\) and \\(45°, 60°, 75°\\). Are they similar? Why?","answer":"Yes, by AA (all angles match)","solution":"When all corresponding angles are equal, the triangles are similar by AA."},{"type":"regular","q":"If \\(\\triangle ABC \\sim \\triangle XYZ\\) with scale factor \\(2\\), and \\(AB = 7\\), find \\(XY\\).","answer":"\\(14\\)","solution":"Multiply the corresponding side by the scale factor: \\(7 \\times 2 = 14\\)."},{"type":"regular","q":"Two triangles have two angles of \\(50°\\) and \\(70°\\) each. Are they similar?","answer":"Yes","solution":"Two matching angles (AA) guarantee similarity."},{"type":"regular","q":"If \\(\\triangle MNO \\sim \\triangle DEF\\) and \\(MN = 10\\), \\(DE = 15\\), what is the scale factor from \\(MNO\\) to \\(DEF\\)?","answer":"\\(\\dfrac{3}{2}\\)","solution":"Scale factor is \\(\\dfrac{DE}{MN} = \\dfrac{15}{10} = \\dfrac{3}{2}\\)."},{"type":"regular","q":"Triangle \\(ABC\\) has angles \\(35°, 65°, 80°\\). Triangle \\(DEF\\) has angles \\(35°, 65°, 80°\\). Similar?","answer":"Yes","solution":"All three angles match, so by AA (or AAA), the triangles are similar."},{"type":"regular","q":"If \\(\\triangle JKL \\sim \\triangle RST\\) with scale factor \\(\\dfrac{1}{3}\\), and \\(RS = 18\\), find \\(JK\\).","answer":"\\(6\\)","solution":"Multiply the corresponding side by the scale factor: \\(18 \\times \\dfrac{1}{3} = 6\\)."},{"type":"regular","q":"Two triangles both have a right angle and a \\(40°\\) angle. Are they similar?","answer":"Yes","solution":"Two matching angles (the right angle and the \\(40°\\) angle) establish AA similarity."},{"type":"regular","q":"If \\(\\triangle GHI \\sim \\triangle UVW\\) and \\(GH = 5\\), \\(UV = 20\\), what is the scale factor from \\(GHI\\) to \\(UVW\\)?","answer":"\\(4\\)","solution":"Scale factor is \\(\\dfrac{UV}{GH} = \\dfrac{20}{5} = 4\\)."},{"type":"word","q":"A 12-ft telephone pole casts an 8-ft shadow. At the same time, a building casts a 20-ft shadow. How tall is the building?","answer":"30 ft","solution":"Set up the proportion \\(\\dfrac{12}{8} = \\dfrac{h}{20}\\); cross-multiply to get \\(h = 30\\)."},{"type":"word","q":"A 6-ft person casts a 4-ft shadow. A nearby tree casts a 14-ft shadow. How tall is the tree?","answer":"21 ft","solution":"Set up \\(\\dfrac{6}{4} = \\dfrac{h}{14}\\); cross-multiply to get \\(h = 21\\)."},{"type":"word","q":"A 10-ft ladder casts a 6-ft shadow. A building casts a 24-ft shadow. What is the building's height?","answer":"40 ft","solution":"Set up \\(\\dfrac{10}{6} = \\dfrac{h}{24}\\); cross-multiply to get \\(h = 40\\)."},{"type":"word","q":"A 4-ft child casts a 2.5-ft shadow. A flagpole casts a 10-ft shadow. How tall is the flagpole?","answer":"16 ft","solution":"Set up \\(\\dfrac{4}{2.5} = \\dfrac{h}{10}\\); cross-multiply to get \\(h = 16\\)."},{"type":"word","q":"A 9-ft fence casts a 3-ft shadow. A building casts a 12-ft shadow. What is the building's height?","answer":"36 ft","solution":"Set up \\(\\dfrac{9}{3} = \\dfrac{h}{12}\\); cross-multiply to get \\(h = 36\\)."},{"type":"word","q":"A 5-ft post casts a 7-ft shadow. A tower casts a 28-ft shadow. How tall is the tower?","answer":"20 ft","solution":"Set up \\(\\dfrac{5}{7} = \\dfrac{h}{28}\\); cross-multiply to get \\(h = 20\\)."}]);
  add("geometry", "g6", 2, [{"type":"regular","q":"Two similar rectangles have sides 5 and 8. The larger rectangle has a side of 16. Find the other side of the larger rectangle.","answer":"10","solution":"The scale factor is \\(\\dfrac{16}{8} = 2\\), so the other side is \\(5 \\times 2 = 10\\)."},{"type":"regular","q":"Two similar pentagons have a scale factor of 3. If the smaller pentagon has a perimeter of 25 cm, what is the larger pentagon's perimeter?","answer":"75 cm","solution":"Perimeter scales linearly with the scale factor: \\(25 \\times 3 = 75\\) cm."},{"type":"regular","q":"Two similar triangles have a scale factor of 2. If the smaller triangle has an area of 20 sq in, what is the larger triangle's area?","answer":"80 sq in","solution":"Area scales as the square of the scale factor: \\(20 \\times 2^2 = 20 \\times 4 = 80\\) sq in."},{"type":"regular","q":"Two similar rectangles have sides 3 and 7. The larger has a side of 21. Find the other side.","answer":"9","solution":"Scale factor is \\(\\dfrac{21}{7} = 3\\), so the other side is \\(3 \\times 3 = 9\\)."},{"type":"regular","q":"Two similar hexagons have a scale factor of \\(\\dfrac{1}{2}\\). If the larger hexagon has a perimeter of 48 cm, what is the smaller hexagon's perimeter?","answer":"24 cm","solution":"Perimeter of smaller is \\(48 \\times \\dfrac{1}{2} = 24\\) cm."},{"type":"regular","q":"Two similar quadrilaterals have a scale factor of 4. If the smaller has an area of 15 sq ft, what is the larger's area?","answer":"240 sq ft","solution":"Area scales as the square of the scale factor: \\(15 \\times 4^2 = 15 \\times 16 = 240\\) sq ft."},{"type":"regular","q":"Two similar trapezoids have sides 6 and 10. The larger has a corresponding side of 25. Find the other corresponding side.","answer":"15","solution":"Scale factor is \\(\\dfrac{25}{10} = 2.5\\), so the other side is \\(6 \\times 2.5 = 15\\)."},{"type":"regular","q":"Two similar parallelograms have a scale factor of 3. If the smaller has a perimeter of 14 in, what is the larger's perimeter?","answer":"42 in","solution":"Perimeter scales linearly: \\(14 \\times 3 = 42\\) in."},{"type":"regular","q":"Two similar octagons have a scale factor of \\(\\dfrac{2}{3}\\). If the larger has an area of 108 sq cm, what is the smaller's area?","answer":"48 sq cm","solution":"Area of smaller is \\(108 \\times \\left(\\dfrac{2}{3}\\right)^2 = 108 \\times \\dfrac{4}{9} = 48\\) sq cm."},{"type":"word","q":"Two similar rectangular gardens have a scale factor of 2. The smaller garden has an area of 60 sq m. What is the larger garden's area?","answer":"240 sq m","solution":"Area scales as the square of the scale factor: \\(60 \\times 2^2 = 60 \\times 4 = 240\\) sq m."},{"type":"word","q":"A scale model of a room has dimensions 2 ft by 3 ft. The actual room has a scale factor of 6. What is the actual room's area?","answer":"216 sq ft","solution":"Model area is \\(2 \\times 3 = 6\\) sq ft; actual area is \\(6 \\times 6^2 = 216\\) sq ft."},{"type":"word","q":"Two similar floor plans have a scale factor of 4. The smaller plan has a perimeter of 28 ft. What is the larger plan's perimeter?","answer":"112 ft","solution":"Perimeter scales linearly: \\(28 \\times 4 = 112\\) ft."},{"type":"word","q":"A model swimming pool is 1 ft by 1.5 ft. The actual pool has a scale factor of 8. What is the actual pool's area?","answer":"96 sq ft","solution":"Model area is \\(1 \\times 1.5 = 1.5\\) sq ft; actual area is \\(1.5 \\times 8^2 = 1.5 \\times 64 = 96\\) sq ft."},{"type":"word","q":"Two similar tiles have a scale factor of \\(\\dfrac{1}{3}\\). The larger tile has an area of 81 sq in. What is the smaller tile's area?","answer":"9 sq in","solution":"Smaller area is \\(81 \\times \\left(\\dfrac{1}{3}\\right)^2 = 81 \\times \\dfrac{1}{9} = 9\\) sq in."},{"type":"word","q":"A blueprint of a house has a perimeter of 16 in. The actual house has a scale factor of 12. What is the actual house's perimeter?","answer":"192 in","solution":"Perimeter scales linearly: \\(16 \\times 12 = 192\\) in."}]);
  addCum("geometry", "g6", [{"type":"regular","q":"Solve: \\(\\dfrac{8}{x} = \\dfrac{4}{7}\\).","answer":"\\(x = 14\\)","solution":"Cross-multiply: \\(8 \\times 7 = 4x\\), so \\(56 = 4x\\), giving \\(x = 14\\)."},{"type":"regular","q":"Simplify the ratio \\(45 : 60\\).","answer":"\\(3 : 4\\)","solution":"Divide both by their GCD of 15."},{"type":"regular","q":"If \\(\\triangle ABC \\sim \\triangle DEF\\) and \\(AB = 4\\), \\(DE = 12\\), what is the scale factor from \\(ABC\\) to \\(DEF\\)?","answer":"\\(3\\)","solution":"Scale factor is \\(\\dfrac{DE}{AB} = \\dfrac{12}{4} = 3\\)."},{"type":"regular","q":"Two similar squares have sides 3 and 7. What is the ratio of their perimeters?","answer":"\\(3 : 7\\)","solution":"Perimeter ratio equals the side ratio: \\(3 : 7\\)."},{"type":"regular","q":"Two triangles both have a \\(55°\\) angle and a \\(65°\\) angle. Are they similar?","answer":"Yes","solution":"Two matching angles (AA) guarantee similarity."},{"type":"regular","q":"If two similar triangles have a scale factor of 5, what is the ratio of their areas?","answer":"\\(1 : 25\\)","solution":"Area ratio is the square of the scale factor: \\(1 : 5^2 = 1 : 25\\)."},{"type":"regular","q":"Solve: \\(\\dfrac{x}{18} = \\dfrac{7}{9}\\).","answer":"\\(x = 14\\)","solution":"Cross-multiply: \\(9x = 126\\), so \\(x = 14\\)."},{"type":"regular","q":"Two similar rectangles have a scale factor of 2. If the smaller has a perimeter of 20 cm, what is the larger's perimeter?","answer":"40 cm","solution":"Perimeter scales linearly: \\(20 \\times 2 = 40\\) cm."},{"type":"regular","q":"If \\(\\triangle PQR \\sim \\triangle STU\\) with scale factor \\(\\dfrac{1}{4}\\), and \\(ST = 20\\), find \\(PQ\\).","answer":"\\(5\\)","solution":"Multiply the corresponding side by the scale factor: \\(20 \\times \\dfrac{1}{4} = 5\\)."},{"type":"regular","q":"Two similar pentagons have areas 16 sq in and 64 sq in. What is their scale factor?","answer":"\\(\\dfrac{1}{2}\\)","solution":"Scale factor is the square root of the area ratio: \\(\\sqrt{\\dfrac{16}{64}} = \\sqrt{\\dfrac{1}{4}} = \\dfrac{1}{2}\\)."},{"type":"regular","q":"Simplify the ratio \\(56 : 72\\).","answer":"\\(7 : 9\\)","solution":"Divide both by their GCD of 8."},{"type":"regular","q":"Two similar triangles have areas 25 sq ft and 100 sq ft. What is their scale factor?","answer":"\\(\\dfrac{1}{2}\\)","solution":"Scale factor is \\(\\sqrt{\\dfrac{25}{100}} = \\sqrt{\\dfrac{1}{4}} = \\dfrac{1}{2}\\)."},{"type":"regular","q":"Solve: \\(\\dfrac{12}{x} = \\dfrac{3}{5}\\).","answer":"\\(x = 20\\)","solution":"Cross-multiply: \\(12 \\times 5 = 3x\\), so \\(60 = 3x\\), giving \\(x = 20\\)."},{"type":"regular","q":"Two similar hexagons have a scale factor of \\(\\dfrac{3}{2}\\). If the smaller has an area of 32 sq cm, what is the larger's area?","answer":"72 sq cm","solution":"Larger area is \\(32 \\times \\left(\\dfrac{3}{2}\\right)^2 = 32 \\times \\dfrac{9}{4} = 72\\) sq cm."},{"type":"word","q":"A 7-ft pole casts a 5-ft shadow. A building casts an 18-ft shadow. How tall is the building?","answer":"25.2 ft","solution":"Set up \\(\\dfrac{7}{5} = \\dfrac{h}{18}\\); cross-multiply to get \\(h = 25.2\\) ft."},{"type":"word","q":"A recipe uses 4 cups of flour for every 6 cups of sugar. How much flour is needed for 18 cups of sugar?","answer":"12 cups","solution":"Set up \\(\\dfrac{4}{6} = \\dfrac{x}{18}\\); cross-multiply to get \\(x = 12\\)."},{"type":"word","q":"A map scale is 1 in = 100 mi. How many inches represent 450 miles?","answer":"4.5 in","solution":"Divide 450 by 100 to get 4.5 in."},{"type":"word","q":"Two similar model cars have a scale factor of 2. The smaller model costs \\$30. If cost scales with area, what does the larger model cost?","answer":"\\$120","solution":"Cost scales with area, which is the square of the scale factor: \\(30 \\times 2^2 = 30 \\times 4 = 120\\) dollars."},{"type":"word","q":"A scale model of a building is 2 ft tall. The actual building has a scale factor of 15. How tall is the actual building in feet?","answer":"30 ft","solution":"Multiply the model height by the scale factor: \\(2 \\times 15 = 30\\) ft."},{"type":"word","q":"A concrete path has dimensions 3 ft by 4 ft. A similar path is built with a scale factor of 3. What is the larger path's area?","answer":"108 sq ft","solution":"Original area is \\(3 \\times 4 = 12\\) sq ft; scaled area is \\(12 \\times 3^2 = 108\\) sq ft."},{"type":"word","q":"A 6-ft person casts a 3-ft shadow. How long is the shadow of a 10-ft flagpole?","answer":"5 ft","solution":"Set up \\(\\dfrac{6}{3} = \\dfrac{10}{s}\\); cross-multiply to get \\(s = 5\\) ft."},{"type":"word","q":"A blueprint has a scale of 1 cm = 3 m. A room is drawn as 5 cm by 7 cm. What is the actual room's area?","answer":"315 sq m","solution":"Actual dimensions are \\(15 \\text{ m} \\times 21 \\text{ m}\\); area is \\(15 \\times 21 = 315\\) sq m."},{"type":"word","q":"Two similar triangular gardens have areas 36 sq ft and 144 sq ft. What is the ratio of their perimeters?","answer":"\\(1 : 2\\)","solution":"Perimeter ratio is the square root of the area ratio: \\(\\sqrt{\\dfrac{36}{144}} = \\sqrt{\\dfrac{1}{4}} = \\dfrac{1}{2}\\), so \\(1 : 2\\)."}]);
  add("geometry", "g7", 0, [{"type":"regular","q":"Find the hypotenuse of a right triangle with legs 5 and 12.","answer":"13","solution":"Use $c = \\sqrt{5^2 + 12^2} = \\sqrt{25 + 144} = \\sqrt{169} = 13$."},{"type":"regular","q":"A right triangle has hypotenuse 25 and one leg 7. Find the other leg.","answer":"24","solution":"Use $b = \\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576} = 24$."},{"type":"regular","q":"Find the hypotenuse of a right triangle with legs 8 and 15.","answer":"17","solution":"Use $c = \\sqrt{8^2 + 15^2} = \\sqrt{64 + 225} = \\sqrt{289} = 17$."},{"type":"regular","q":"A right triangle has hypotenuse 20 and one leg 12. Find the other leg.","answer":"16","solution":"Use $b = \\sqrt{20^2 - 12^2} = \\sqrt{400 - 144} = \\sqrt{256} = 16$."},{"type":"regular","q":"Is $(6, 8, 10)$ a Pythagorean triple?","answer":"Yes","solution":"Check: $6^2 + 8^2 = 36 + 64 = 100 = 10^2$."},{"type":"regular","q":"Find the hypotenuse of a right triangle with legs 20 and 21.","answer":"29","solution":"Use $c = \\sqrt{20^2 + 21^2} = \\sqrt{400 + 441} = \\sqrt{841} = 29$."},{"type":"regular","q":"A right triangle has hypotenuse 13 and one leg 5. Find the other leg.","answer":"12","solution":"Use $b = \\sqrt{13^2 - 5^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$."},{"type":"regular","q":"Find the diagonal of a $7 \\times 24$ rectangle.","answer":"25","solution":"Use $d = \\sqrt{7^2 + 24^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25$."},{"type":"regular","q":"A right triangle has hypotenuse 10 and one leg 6. Find the other leg.","answer":"8","solution":"Use $b = \\sqrt{10^2 - 6^2} = \\sqrt{100 - 36} = \\sqrt{64} = 8$."},{"type":"word","q":"A rope of length 15 m is stretched from the top of a 9 m pole to the ground. How far from the base of the pole does the rope touch the ground?","answer":"12 m","solution":"Use $b = \\sqrt{15^2 - 9^2} = \\sqrt{225 - 81} = \\sqrt{144} = 12$."},{"type":"word","q":"A soccer field is 100 m long and 60 m wide. What is the distance from one corner to the opposite corner?","answer":"$20\\sqrt{34}$ m or $\\approx 116.6$ m","solution":"Use $d = \\sqrt{100^2 + 60^2} = \\sqrt{10000 + 3600} = \\sqrt{13600} = 20\\sqrt{34}$."},{"type":"word","q":"A tree is 24 ft tall and casts a shadow 7 ft long. If a cable runs from the top of the tree to the end of the shadow, how long is the cable?","answer":"25 ft","solution":"Use $c = \\sqrt{24^2 + 7^2} = \\sqrt{576 + 49} = \\sqrt{625} = 25$."},{"type":"word","q":"A boat travels 20 km north and then 15 km east. What is its distance from the starting point?","answer":"25 km","solution":"Use $d = \\sqrt{20^2 + 15^2} = \\sqrt{400 + 225} = \\sqrt{625} = 25$."},{"type":"word","q":"A painting is 18 inches wide and 24 inches tall. What is the length of the diagonal of the frame?","answer":"30 inches","solution":"Use $d = \\sqrt{18^2 + 24^2} = \\sqrt{324 + 576} = \\sqrt{900} = 30$."},{"type":"word","q":"A staircase has a vertical rise of 10 ft and a horizontal run of 24 ft. What is the length of the stair railing?","answer":"26 ft","solution":"Use $c = \\sqrt{10^2 + 24^2} = \\sqrt{100 + 576} = \\sqrt{676} = 26$."}]);
  add("geometry", "g7", 1, [{"type":"regular","q":"In a $45°\\text{-}45°\\text{-}90°$ triangle with legs 5, find the hypotenuse.","answer":"$5\\sqrt{2}$","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, hypotenuse $= \\text{leg} \\times \\sqrt{2} = 5\\sqrt{2}$."},{"type":"regular","q":"In a $30°\\text{-}60°\\text{-}90°$ triangle with short leg 8, find the long leg.","answer":"$8\\sqrt{3}$","solution":"In a $30°\\text{-}60°\\text{-}90°$ triangle, long leg $= \\text{short leg} \\times \\sqrt{3} = 8\\sqrt{3}$."},{"type":"regular","q":"In a $30°\\text{-}60°\\text{-}90°$ triangle with hypotenuse 16, find the short leg.","answer":"8","solution":"In a $30°\\text{-}60°\\text{-}90°$ triangle, short leg $= \\frac{\\text{hypotenuse}}{2} = \\frac{16}{2} = 8$."},{"type":"regular","q":"In a $45°\\text{-}45°\\text{-}90°$ triangle with hypotenuse 12, find the leg length.","answer":"$6\\sqrt{2}$","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, leg $= \\frac{\\text{hypotenuse}}{\\sqrt{2}} = \\frac{12}{\\sqrt{2}} = 6\\sqrt{2}$."},{"type":"regular","q":"In a $30°\\text{-}60°\\text{-}90°$ triangle with long leg 6, find the short leg.","answer":"$2\\sqrt{3}$","solution":"In a $30°\\text{-}60°\\text{-}90°$ triangle, short leg $= \\frac{\\text{long leg}}{\\sqrt{3}} = \\frac{6}{\\sqrt{3}} = 2\\sqrt{3}$."},{"type":"regular","q":"In a $45°\\text{-}45°\\text{-}90°$ triangle with legs 9, find the hypotenuse.","answer":"$9\\sqrt{2}$","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, hypotenuse $= \\text{leg} \\times \\sqrt{2} = 9\\sqrt{2}$."},{"type":"regular","q":"In a $30°\\text{-}60°\\text{-}90°$ triangle with short leg 3, find the hypotenuse.","answer":"6","solution":"In a $30°\\text{-}60°\\text{-}90°$ triangle, hypotenuse $= 2 \\times \\text{short leg} = 2 \\times 3 = 6$."},{"type":"regular","q":"In a $30°\\text{-}60°\\text{-}90°$ triangle with hypotenuse 24, find the long leg.","answer":"$12\\sqrt{3}$","solution":"In a $30°\\text{-}60°\\text{-}90°$ triangle, long leg $= \\text{short leg} \\times \\sqrt{3} = 12 \\times \\sqrt{3} = 12\\sqrt{3}$."},{"type":"regular","q":"In a $45°\\text{-}45°\\text{-}90°$ triangle with hypotenuse $8\\sqrt{2}$, find the leg length.","answer":"8","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, leg $= \\frac{\\text{hypotenuse}}{\\sqrt{2}} = \\frac{8\\sqrt{2}}{\\sqrt{2}} = 8$."},{"type":"word","q":"A square has a side length of 6 m. What is the length of its diagonal?","answer":"$6\\sqrt{2}$ m","solution":"A square's diagonal forms a $45°\\text{-}45°\\text{-}90°$ triangle; diagonal $= 6\\sqrt{2}$."},{"type":"word","q":"An isosceles right triangle has legs of 4 inches. Find the hypotenuse.","answer":"$4\\sqrt{2}$ inches","solution":"An isosceles right triangle is $45°\\text{-}45°\\text{-}90°$; hypotenuse $= 4\\sqrt{2}$."},{"type":"word","q":"A square has a diagonal of 14 cm. What is the length of each side?","answer":"$7\\sqrt{2}$ cm","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, side $= \\frac{\\text{diagonal}}{\\sqrt{2}} = \\frac{14}{\\sqrt{2}} = 7\\sqrt{2}$."},{"type":"word","q":"An equilateral triangle has a side length of 10. What is the height of the triangle?","answer":"$5\\sqrt{3}$","solution":"The height of an equilateral triangle forms a $30°\\text{-}60°\\text{-}90°$ triangle; height $= \\frac{\\text{side}}{2} \\times \\sqrt{3} = 5\\sqrt{3}$."},{"type":"word","q":"A rhombus has diagonals of length 12 and $12\\sqrt{3}$. If the sides are equal, what is the side length?","answer":"$12$","solution":"The diagonals form $30°\\text{-}60°\\text{-}90°$ triangles; use the ratio to find side $= 12$."},{"type":"word","q":"A rectangular garden is a square with side length 8 ft. What is the distance across the diagonal?","answer":"$8\\sqrt{2}$ ft","solution":"A square with side 8 has diagonal $= 8\\sqrt{2}$ from the $45°\\text{-}45°\\text{-}90°$ triangle ratio."}]);
  add("geometry", "g7", 2, [{"type":"regular","q":"In a right triangle, opposite = 6, hypotenuse = 10. Find $\\sin\\theta$.","answer":"$\\frac{3}{5}$","solution":"$\\sin\\theta = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{6}{10} = \\frac{3}{5}$."},{"type":"regular","q":"In a right triangle, adjacent = 9, hypotenuse = 15. Find $\\cos\\theta$.","answer":"$\\frac{3}{5}$","solution":"$\\cos\\theta = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{9}{15} = \\frac{3}{5}$."},{"type":"regular","q":"In a right triangle, opposite = 8, adjacent = 6. Find $\\tan\\theta$.","answer":"$\\frac{4}{3}$","solution":"$\\tan\\theta = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{8}{6} = \\frac{4}{3}$."},{"type":"regular","q":"In a right triangle, $\\sin\\theta = \\frac{5}{13}$. Find $\\cos\\theta$ if the hypotenuse is 13.","answer":"$\\frac{12}{13}$","solution":"If opposite $= 5$ and hypotenuse $= 13$, then adjacent $= \\sqrt{13^2 - 5^2} = 12$, so $\\cos\\theta = \\frac{12}{13}$."},{"type":"regular","q":"In a right triangle, $\\tan\\theta = \\frac{3}{4}$. Find $\\sin\\theta$.","answer":"$\\frac{3}{5}$","solution":"If opposite $= 3$ and adjacent $= 4$, then hypotenuse $= 5$, so $\\sin\\theta = \\frac{3}{5}$."},{"type":"regular","q":"In a right triangle, opposite = 12, hypotenuse = 13. Find $\\cos\\theta$.","answer":"$\\frac{5}{13}$","solution":"If opposite $= 12$ and hypotenuse $= 13$, then adjacent $= \\sqrt{13^2 - 12^2} = 5$, so $\\cos\\theta = \\frac{5}{13}$."},{"type":"regular","q":"In a right triangle, adjacent = 11, hypotenuse = 61. Find $\\sin\\theta$.","answer":"$\\frac{60}{61}$","solution":"If adjacent $= 11$ and hypotenuse $= 61$, then opposite $= \\sqrt{61^2 - 11^2} = 60$, so $\\sin\\theta = \\frac{60}{61}$."},{"type":"regular","q":"In a right triangle, opposite = 9, adjacent = 40. Find $\\tan\\theta$.","answer":"$\\frac{9}{40}$","solution":"$\\tan\\theta = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{9}{40}$."},{"type":"regular","q":"In a right triangle, $\\sin\\theta = 0.6$. Find $\\cos\\theta$.","answer":"$0.8$","solution":"If $\\sin\\theta = 0.6 = \\frac{3}{5}$, then $\\cos\\theta = \\frac{4}{5} = 0.8$ using the Pythagorean identity."},{"type":"word","q":"A ramp rises 5 ft over a horizontal distance of 12 ft. Find the angle of elevation to the nearest degree.","answer":"$23°$","solution":"$\\tan\\theta = \\frac{5}{12}$, so $\\theta = \\arctan(\\frac{5}{12}) \\approx 23°$."},{"type":"word","q":"From a point 50 m away from a building, the angle of elevation to the top is $35°$. What is the height of the building?","answer":"$\\approx 35$ m","solution":"$\\tan(35°) = \\frac{h}{50}$, so $h = 50 \\tan(35°) \\approx 35$ m."},{"type":"word","q":"A ladder leans against a wall at a $60°$ angle with the ground. If the ladder is 10 ft long, how high does it reach on the wall?","answer":"$5\\sqrt{3}$ ft or $\\approx 8.66$ ft","solution":"$\\sin(60°) = \\frac{h}{10}$, so $h = 10 \\sin(60°) = 10 \\cdot \\frac{\\sqrt{3}}{2} = 5\\sqrt{3}$."},{"type":"word","q":"A pilot flying at 3000 ft altitude sees the airport at an angle of depression of $12°$. What is the horizontal distance to the airport?","answer":"$\\approx 14143$ ft","solution":"$\\tan(12°) = \\frac{3000}{d}$, so $d = \\frac{3000}{\\tan(12°)} \\approx 14143$ ft."},{"type":"word","q":"A tree casts a shadow 20 m long when the sun's angle of elevation is $40°$. How tall is the tree?","answer":"$\\approx 16.78$ m","solution":"$\\tan(40°) = \\frac{h}{20}$, so $h = 20 \\tan(40°) \\approx 16.78$ m."},{"type":"word","q":"A cable runs from the top of a 30 m pole to a point 40 m away on the ground. What angle does the cable make with the ground?","answer":"$\\approx 37°$","solution":"$\\tan\\theta = \\frac{30}{40} = 0.75$, so $\\theta = \\arctan(0.75) \\approx 37°$."}]);
  addCum("geometry", "g7", [{"type":"regular","q":"Find the hypotenuse of a right triangle with legs 11 and 60.","answer":"61","solution":"Use $c = \\sqrt{11^2 + 60^2} = \\sqrt{121 + 3600} = \\sqrt{3721} = 61$."},{"type":"regular","q":"In a $45°\\text{-}45°\\text{-}90°$ triangle with hypotenuse $10\\sqrt{2}$, find each leg.","answer":"10","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, leg $= \\frac{\\text{hypotenuse}}{\\sqrt{2}} = \\frac{10\\sqrt{2}}{\\sqrt{2}} = 10$."},{"type":"regular","q":"In a $30°\\text{-}60°\\text{-}90°$ triangle with short leg 6, find the hypotenuse.","answer":"12","solution":"In a $30°\\text{-}60°\\text{-}90°$ triangle, hypotenuse $= 2 \\times \\text{short leg} = 2 \\times 6 = 12$."},{"type":"regular","q":"In a right triangle, opposite = 15, hypotenuse = 17. Find $\\cos\\theta$.","answer":"$\\frac{8}{17}$","solution":"If opposite $= 15$ and hypotenuse $= 17$, then adjacent $= \\sqrt{17^2 - 15^2} = 8$, so $\\cos\\theta = \\frac{8}{17}$."},{"type":"regular","q":"A right triangle has hypotenuse 29 and one leg 20. Find the other leg.","answer":"21","solution":"Use $b = \\sqrt{29^2 - 20^2} = \\sqrt{841 - 400} = \\sqrt{441} = 21$."},{"type":"regular","q":"Is $(9, 12, 15)$ a Pythagorean triple?","answer":"Yes","solution":"Check: $9^2 + 12^2 = 81 + 144 = 225 = 15^2$."},{"type":"regular","q":"In a $30°\\text{-}60°\\text{-}90°$ triangle with hypotenuse 18, find the long leg.","answer":"$9\\sqrt{3}$","solution":"Short leg $= \\frac{18}{2} = 9$; long leg $= 9\\sqrt{3}$."},{"type":"regular","q":"Find the diagonal of a $5 \\times 12$ rectangle.","answer":"13","solution":"Use $d = \\sqrt{5^2 + 12^2} = \\sqrt{25 + 144} = \\sqrt{169} = 13$."},{"type":"regular","q":"In a right triangle, $\\sin\\theta = \\frac{7}{25}$. Find $\\tan\\theta$.","answer":"$\\frac{7}{24}$","solution":"If opposite $= 7$ and hypotenuse $= 25$, then adjacent $= 24$, so $\\tan\\theta = \\frac{7}{24}$."},{"type":"regular","q":"A square has a diagonal of $5\\sqrt{2}$ cm. What is the side length?","answer":"5 cm","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, side $= \\frac{\\text{diagonal}}{\\sqrt{2}} = \\frac{5\\sqrt{2}}{\\sqrt{2}} = 5$."},{"type":"regular","q":"In a right triangle, adjacent = 5, opposite = 12. Find the hypotenuse.","answer":"13","solution":"Use $c = \\sqrt{5^2 + 12^2} = \\sqrt{25 + 144} = \\sqrt{169} = 13$."},{"type":"regular","q":"In a $45°\\text{-}45°\\text{-}90°$ triangle with legs 3, find the hypotenuse.","answer":"$3\\sqrt{2}$","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, hypotenuse $= \\text{leg} \\times \\sqrt{2} = 3\\sqrt{2}$."},{"type":"word","q":"A surveyor measures a right triangle with legs 40 m and 30 m. What is the hypotenuse?","answer":"50 m","solution":"Use $c = \\sqrt{40^2 + 30^2} = \\sqrt{1600 + 900} = \\sqrt{2500} = 50$."},{"type":"word","q":"An isosceles right triangle has a hypotenuse of 8 inches. What is the length of each leg?","answer":"$4\\sqrt{2}$ inches","solution":"In a $45°\\text{-}45°\\text{-}90°$ triangle, leg $= \\frac{\\text{hypotenuse}}{\\sqrt{2}} = \\frac{8}{\\sqrt{2}} = 4\\sqrt{2}$."},{"type":"word","q":"From a point 100 m away from a tower, the angle of elevation to the top is $45°$. What is the height of the tower?","answer":"100 m","solution":"$\\tan(45°) = 1 = \\frac{h}{100}$, so $h = 100$ m."},{"type":"word","q":"A ramp makes a $25°$ angle with the ground. If the ramp is 8 m long, what is the vertical rise?","answer":"$\\approx 3.38$ m","solution":"$\\sin(25°) = \\frac{h}{8}$, so $h = 8 \\sin(25°) \\approx 3.38$ m."},{"type":"word","q":"A ship travels 12 km north and then 5 km east. What is the distance from the starting point?","answer":"13 km","solution":"Use $d = \\sqrt{12^2 + 5^2} = \\sqrt{144 + 25} = \\sqrt{169} = 13$."},{"type":"word","q":"An equilateral triangle has a side length of 8. What is the height?","answer":"$4\\sqrt{3}$","solution":"The height forms a $30°\\text{-}60°\\text{-}90°$ triangle; height $= \\frac{8}{2} \\times \\sqrt{3} = 4\\sqrt{3}$."},{"type":"word","q":"A ladder 15 ft long leans against a wall. If the base is 9 ft from the wall, how high does it reach?","answer":"12 ft","solution":"Use $h = \\sqrt{15^2 - 9^2} = \\sqrt{225 - 81} = \\sqrt{144} = 12$."},{"type":"word","q":"From 80 m away, the angle of elevation to a building's top is $28°$. What is the building's height?","answer":"$\\approx 42.5$ m","solution":"$\\tan(28°) = \\frac{h}{80}$, so $h = 80 \\tan(28°) \\approx 42.5$ m."},{"type":"word","q":"A right triangle has a $30°$ angle. If the side opposite the $30°$ angle is 7, what is the hypotenuse?","answer":"14","solution":"In a $30°\\text{-}60°\\text{-}90°$ triangle, hypotenuse $= 2 \\times \\text{short leg} = 2 \\times 7 = 14$."},{"type":"word","q":"A diagonal of a square is 12 m. What is the perimeter of the square?","answer":"$24\\sqrt{2}$ m or $\\approx 33.9$ m","solution":"Side $= \\frac{12}{\\sqrt{2}} = 6\\sqrt{2}$; perimeter $= 4 \\times 6\\sqrt{2} = 24\\sqrt{2}$."},{"type":"word","q":"A person 6 ft tall casts a shadow 8 ft long. What is the angle of elevation of the sun?","answer":"$\\approx 37°$","solution":"$\\tan\\theta = \\frac{6}{8} = 0.75$, so $\\theta = \\arctan(0.75) \\approx 37°$."},{"type":"word","q":"A cable from a 40 m pole to a point 30 m away on the ground forms a right triangle. What angle does the cable make with the ground?","answer":"$\\approx 53°$","solution":"$\\tan\\theta = \\frac{40}{30} = \\frac{4}{3}$, so $\\theta = \\arctan(\\frac{4}{3}) \\approx 53°$."}]);
  add("geometry", "g8", 0, [{"type":"regular","q":"Find the area of a triangle with base 12 and height 9.","answer":"54","solution":"Use the formula A = ½ × base × height = ½ × 12 × 9 = 54."},{"type":"regular","q":"What is the area of a circle with radius 4?","answer":"16π","solution":"Use the formula A = πr² = π(4)² = 16π."},{"type":"regular","q":"A square has a side length of 7 cm. What is its area?","answer":"49 sq cm","solution":"Area of a square = side² = 7² = 49 sq cm."},{"type":"regular","q":"Find the area of a parallelogram with base 11 and height 6.","answer":"66","solution":"Use the formula A = base × height = 11 × 6 = 66."},{"type":"regular","q":"A trapezoid has bases 5 and 9, with height 3. What is its area?","answer":"21","solution":"Use the formula A = ½(b₁ + b₂) × h = ½(5 + 9) × 3 = 21."},{"type":"regular","q":"Find the area of a circle with radius 5.","answer":"25π","solution":"Use A = πr² = π(5)² = 25π."},{"type":"regular","q":"A rhombus has diagonals of length 8 and 6. What is its area?","answer":"24","solution":"Area of a rhombus = ½ × d₁ × d₂ = ½ × 8 × 6 = 24."},{"type":"regular","q":"Find the area of a rectangle with length 13 and width 4.","answer":"52 sq units","solution":"Area = length × width = 13 × 4 = 52 sq units."},{"type":"regular","q":"A triangle has base 16 and height 8. What is its area?","answer":"64","solution":"Use A = ½ × base × height = ½ × 16 × 8 = 64."},{"type":"word","q":"A farmer has a triangular field with base 20 m and height 15 m. What is the area of the field?","answer":"150 sq m","solution":"Area of triangle = ½ × 20 × 15 = 150 sq m."},{"type":"word","q":"A circular pizza has a radius of 7 inches. What is the area of the pizza?","answer":"49π sq in","solution":"Area = πr² = π(7)² = 49π sq in."},{"type":"word","q":"A trapezoid-shaped roof has parallel sides of 12 m and 8 m with a height of 5 m. What is its area?","answer":"50 sq m","solution":"Area = ½(b₁ + b₂) × h = ½(12 + 8) × 5 = 50 sq m."},{"type":"word","q":"A parallelogram-shaped playground has a base of 25 m and a height of 12 m. What is its area?","answer":"300 sq m","solution":"Area = base × height = 25 × 12 = 300 sq m."},{"type":"word","q":"A circular rug has a radius of 3 feet. What is the area of the rug?","answer":"9π sq ft","solution":"Area = πr² = π(3)² = 9π sq ft."},{"type":"word","q":"A rectangular wall is 18 feet long and 9 feet wide. How much paint is needed to cover it (in square feet)?","answer":"162 sq ft","solution":"Area = length × width = 18 × 9 = 162 sq ft."}]);
  add("geometry", "g8", 1, [{"type":"regular","q":"Find the surface area of a cube with edge length 6.","answer":"216","solution":"Surface area = 6s² = 6(6)² = 216."},{"type":"regular","q":"What is the surface area of a sphere with radius 4?","answer":"64π","solution":"Surface area = 4πr² = 4π(4)² = 64π."},{"type":"regular","q":"A rectangular prism has dimensions 3 × 5 × 7. What is its surface area?","answer":"142","solution":"SA = 2(lw + lh + wh) = 2(15 + 21 + 35) = 142."},{"type":"regular","q":"Find the lateral surface area of a cone with radius 4 and slant height 10.","answer":"40π","solution":"Lateral SA = πrl = π(4)(10) = 40π."},{"type":"regular","q":"A cylinder has radius 3 and height 8. What is its total surface area?","answer":"66π","solution":"SA = 2πr² + 2πrh = 2π(9) + 2π(3)(8) = 18π + 48π = 66π."},{"type":"regular","q":"Find the surface area of a cube with edge 4.","answer":"96","solution":"Surface area = 6s² = 6(4)² = 96."},{"type":"regular","q":"A sphere has radius 2. What is its surface area?","answer":"16π","solution":"Surface area = 4πr² = 4π(2)² = 16π."},{"type":"regular","q":"A rectangular prism has dimensions 2 × 6 × 8. Find its surface area.","answer":"152","solution":"SA = 2(lw + lh + wh) = 2(12 + 16 + 48) = 152."},{"type":"regular","q":"Find the lateral surface area of a cone with radius 3 and slant height 9.","answer":"27π","solution":"Lateral SA = πrl = π(3)(9) = 27π."},{"type":"word","q":"A gift box is shaped like a cube with edge length 5 inches. How much wrapping paper is needed to cover it?","answer":"150 sq in","solution":"Surface area = 6s² = 6(5)² = 150 sq in."},{"type":"word","q":"A spherical ball has a radius of 6 cm. What is its surface area?","answer":"144π sq cm","solution":"Surface area = 4πr² = 4π(6)² = 144π sq cm."},{"type":"word","q":"A cylindrical storage tank has radius 5 m and height 12 m. What is its total surface area?","answer":"170π sq m","solution":"SA = 2πr² + 2πrh = 2π(25) + 2π(5)(12) = 50π + 120π = 170π sq m."},{"type":"word","q":"A rectangular prism-shaped aquarium has dimensions 4 ft × 3 ft × 2 ft. What is its surface area?","answer":"52 sq ft","solution":"SA = 2(lw + lh + wh) = 2(12 + 8 + 6) = 52 sq ft."},{"type":"word","q":"A cone-shaped party hat has radius 2 inches and slant height 8 inches. What is its lateral surface area?","answer":"16π sq in","solution":"Lateral SA = πrl = π(2)(8) = 16π sq in."},{"type":"word","q":"A cube-shaped die has edge length 1 cm. What is its total surface area?","answer":"6 sq cm","solution":"Surface area = 6s² = 6(1)² = 6 sq cm."}]);
  add("geometry", "g8", 2, [{"type":"regular","q":"Find the volume of a rectangular prism with dimensions 3 × 4 × 8.","answer":"96","solution":"Volume = length × width × height = 3 × 4 × 8 = 96."},{"type":"regular","q":"What is the volume of a cylinder with radius 2 and height 9?","answer":"36π","solution":"Volume = πr²h = π(2)²(9) = 36π."},{"type":"regular","q":"A cone has radius 4 and height 6. What is its volume?","answer":"32π","solution":"Volume = ⅓πr²h = ⅓π(4)²(6) = 32π."},{"type":"regular","q":"Find the volume of a sphere with radius 3.","answer":"36π","solution":"Volume = ⁴⁄₃πr³ = ⁴⁄₃π(3)³ = 36π."},{"type":"regular","q":"A cube has edge length 5. What is its volume?","answer":"125","solution":"Volume = s³ = 5³ = 125."},{"type":"regular","q":"Find the volume of a rectangular prism with dimensions 2 × 7 × 5.","answer":"70","solution":"Volume = 2 × 7 × 5 = 70."},{"type":"regular","q":"A cylinder has radius 3 and height 5. What is its volume?","answer":"45π","solution":"Volume = πr²h = π(3)²(5) = 45π."},{"type":"regular","q":"A cone has radius 2 and height 9. What is its volume?","answer":"12π","solution":"Volume = ⅓πr²h = ⅓π(2)²(9) = 12π."},{"type":"regular","q":"Find the volume of a sphere with radius 2.","answer":"32π/3","solution":"Volume = ⁴⁄₃πr³ = ⁴⁄₃π(2)³ = 32π/3."},{"type":"word","q":"A rectangular storage box has dimensions 10 ft × 6 ft × 4 ft. What is its volume?","answer":"240 cubic ft","solution":"Volume = length × width × height = 10 × 6 × 4 = 240 cubic ft."},{"type":"word","q":"A cylindrical water tank has radius 4 m and height 7 m. What is its volume?","answer":"112π cubic m","solution":"Volume = πr²h = π(4)²(7) = 112π cubic m."},{"type":"word","q":"A cone-shaped tent has radius 3 m and height 8 m. What is its volume?","answer":"24π cubic m","solution":"Volume = ⅓πr²h = ⅓π(3)²(8) = 24π cubic m."},{"type":"word","q":"A spherical balloon has radius 5 inches. What is its volume?","answer":"500π/3 cubic in","solution":"Volume = ⁴⁄₃πr³ = ⁴⁄₃π(5)³ = 500π/3 cubic in."},{"type":"word","q":"A cube-shaped container has edge length 6 cm. What is its volume?","answer":"216 cubic cm","solution":"Volume = s³ = 6³ = 216 cubic cm."},{"type":"word","q":"A cylindrical can has radius 2 inches and height 6 inches. What is its volume?","answer":"24π cubic in","solution":"Volume = πr²h = π(2)²(6) = 24π cubic in."}]);
  addCum("geometry", "g8", [{"type":"regular","q":"Find the area of a triangle with base 14 and height 6.","answer":"42","solution":"Area = ½ × base × height = ½ × 14 × 6 = 42."},{"type":"regular","q":"What is the surface area of a cube with edge 3?","answer":"54","solution":"Surface area = 6s² = 6(3)² = 54."},{"type":"regular","q":"Find the volume of a rectangular prism with dimensions 5 × 6 × 2.","answer":"60","solution":"Volume = 5 × 6 × 2 = 60."},{"type":"regular","q":"A circle has radius 8. What is its area?","answer":"64π","solution":"Area = πr² = π(8)² = 64π."},{"type":"regular","q":"Find the surface area of a sphere with radius 6.","answer":"144π","solution":"Surface area = 4πr² = 4π(6)² = 144π."},{"type":"regular","q":"What is the volume of a cylinder with radius 2 and height 7?","answer":"28π","solution":"Volume = πr²h = π(2)²(7) = 28π."},{"type":"regular","q":"A trapezoid has bases 7 and 11 with height 4. What is its area?","answer":"36","solution":"Area = ½(b₁ + b₂) × h = ½(7 + 11) × 4 = 36."},{"type":"regular","q":"Find the lateral surface area of a cone with radius 5 and slant height 12.","answer":"60π","solution":"Lateral SA = πrl = π(5)(12) = 60π."},{"type":"regular","q":"A cube has edge length 4. What is its volume?","answer":"64","solution":"Volume = s³ = 4³ = 64."},{"type":"regular","q":"What is the surface area of a rectangular prism with dimensions 3 × 4 × 5?","answer":"94","solution":"SA = 2(lw + lh + wh) = 2(12 + 15 + 20) = 94."},{"type":"word","q":"A circular garden has a radius of 9 meters. What is the area of the garden?","answer":"81π sq m","solution":"Area = πr² = π(9)² = 81π sq m."},{"type":"word","q":"A rectangular box has dimensions 8 inches × 6 inches × 4 inches. What is its volume?","answer":"192 cubic in","solution":"Volume = 8 × 6 × 4 = 192 cubic in."},{"type":"word","q":"A spherical tank has radius 7 feet. What is its surface area?","answer":"196π sq ft","solution":"Surface area = 4πr² = 4π(7)² = 196π sq ft."},{"type":"word","q":"A triangular field has base 25 meters and height 12 meters. What is its area?","answer":"150 sq m","solution":"Area = ½ × 25 × 12 = 150 sq m."},{"type":"word","q":"A cylindrical pipe has radius 3 cm and height 20 cm. What is its volume?","answer":"180π cubic cm","solution":"Volume = πr²h = π(3)²(20) = 180π cubic cm."},{"type":"word","q":"A cone-shaped container has radius 4 inches and height 12 inches. What is its volume?","answer":"64π cubic in","solution":"Volume = ⅓πr²h = ⅓π(4)²(12) = 64π cubic in."},{"type":"word","q":"A parallelogram has base 18 cm and height 10 cm. What is its area?","answer":"180 sq cm","solution":"Area = base × height = 18 × 10 = 180 sq cm."},{"type":"word","q":"A cube-shaped gift box has edge length 7 inches. How much wrapping paper is needed?","answer":"294 sq in","solution":"Surface area = 6s² = 6(7)² = 294 sq in."},{"type":"word","q":"A sphere has radius 4 cm. What is its volume?","answer":"256π/3 cubic cm","solution":"Volume = ⁴⁄₃πr³ = ⁴⁄₃π(4)³ = 256π/3 cubic cm."},{"type":"word","q":"A rectangular prism has dimensions 9 m × 5 m × 3 m. What is its surface area?","answer":"174 sq m","solution":"SA = 2(lw + lh + wh) = 2(45 + 27 + 15) = 174 sq m."},{"type":"word","q":"A circular pizza has area 100π square inches. What is its radius?","answer":"10 inches","solution":"From A = πr², we have 100π = πr², so r² = 100 and r = 10 inches."},{"type":"word","q":"A trapezoid-shaped roof has parallel sides 15 m and 10 m with height 6 m. What is its area?","answer":"75 sq m","solution":"Area = ½(b₁ + b₂) × h = ½(15 + 10) × 6 = 75 sq m."},{"type":"word","q":"A cylindrical storage tank has radius 6 feet and height 15 feet. What is its total surface area?","answer":"252π sq ft","solution":"SA = 2πr² + 2πrh = 2π(36) + 2π(6)(15) = 72π + 180π = 252π sq ft."},{"type":"word","q":"A cone has radius 3 m and slant height 7 m. What is its lateral surface area?","answer":"21π sq m","solution":"Lateral SA = πrl = π(3)(7) = 21π sq m."}]);
  add("geometry", "g9", 0, [{"type":"regular","q":"A fair die is rolled. What is the probability of rolling a 2 or 5?","answer":"\\(\\tfrac{1}{3}\\)","solution":"Two favorable outcomes (2 and 5) out of 6 possible outcomes: \\(\\tfrac{2}{6} = \\tfrac{1}{3}\\)."},{"type":"regular","q":"A bag contains 6 white, 4 black, and 5 yellow balls. What is the probability of drawing a black ball?","answer":"\\(\\tfrac{4}{15}\\)","solution":"4 black balls out of 15 total: \\(\\tfrac{4}{15}\\)."},{"type":"regular","q":"A spinner has 10 equal sections: 4 orange, 3 purple, 3 pink. What is \\(P(\\text{purple})\\)?","answer":"\\(\\tfrac{3}{10}\\)","solution":"3 purple sections out of 10 total: \\(\\tfrac{3}{10}\\)."},{"type":"regular","q":"From a standard deck, what is the probability of drawing a spade?","answer":"\\(\\tfrac{1}{4}\\)","solution":"13 spades out of 52 cards: \\(\\tfrac{13}{52} = \\tfrac{1}{4}\\)."},{"type":"regular","q":"A fair coin is flipped. What is the probability of getting heads or tails?","answer":"1","solution":"All outcomes are either heads or tails, so probability is 1."},{"type":"regular","q":"A die shows numbers 1–6. Probability of rolling an odd number?","answer":"\\(\\tfrac{1}{2}\\)","solution":"Three odd numbers (1, 3, 5) out of 6: \\(\\tfrac{3}{6} = \\tfrac{1}{2}\\)."},{"type":"regular","q":"A box has 2 red, 3 green, and 5 blue pens. Probability of drawing a red pen?","answer":"\\(\\tfrac{1}{5}\\)","solution":"2 red pens out of 10 total: \\(\\tfrac{2}{10} = \\tfrac{1}{5}\\)."},{"type":"regular","q":"A spinner has 12 equal sections: 5 red, 4 blue, 3 yellow. What is \\(P(\\text{not red})\\)?","answer":"\\(\\tfrac{7}{12}\\)","solution":"7 non-red sections out of 12: \\(\\tfrac{7}{12}\\)."},{"type":"regular","q":"A die is rolled. What is the probability of getting a number less than 4?","answer":"\\(\\tfrac{1}{2}\\)","solution":"Three favorable outcomes (1, 2, 3) out of 6: \\(\\tfrac{3}{6} = \\tfrac{1}{2}\\)."},{"type":"word","q":"A jar contains 8 red marbles and 12 blue marbles. If you draw one marble at random, what is the probability it is blue?","answer":"\\(\\tfrac{3}{5}\\)","solution":"12 blue out of 20 total marbles: \\(\\tfrac{12}{20} = \\tfrac{3}{5}\\)."},{"type":"word","q":"A classroom has 15 desks. 9 are occupied and 6 are empty. If you pick a desk at random, what is the probability it is occupied?","answer":"\\(\\tfrac{3}{5}\\)","solution":"9 occupied out of 15 total: \\(\\tfrac{9}{15} = \\tfrac{3}{5}\\)."},{"type":"word","q":"A bag of candies has 20 pieces: 7 cherry, 6 lemon, 4 lime, and 3 grape. What is the probability of drawing a lemon candy?","answer":"\\(\\tfrac{3}{10}\\)","solution":"6 lemon out of 20 total: \\(\\tfrac{6}{20} = \\tfrac{3}{10}\\)."},{"type":"word","q":"In a raffle, 50 tickets are sold. You buy 5 tickets. What is the probability you win (assuming one winner)?","answer":"\\(\\tfrac{1}{10}\\)","solution":"5 of your tickets out of 50 total: \\(\\tfrac{5}{50} = \\tfrac{1}{10}\\)."},{"type":"word","q":"A deck of cards is shuffled. What is the probability of drawing a face card (jack, queen, or king)?","answer":"\\(\\tfrac{3}{13}\\)","solution":"12 face cards out of 52 total: \\(\\tfrac{12}{52} = \\tfrac{3}{13}\\)."},{"type":"word","q":"A student randomly guesses on a true/false question. What is the probability of guessing correctly?","answer":"\\(\\tfrac{1}{2}\\)","solution":"1 correct answer out of 2 possible choices: \\(\\tfrac{1}{2}\\)."}]);
  add("geometry", "g9", 1, [{"type":"regular","q":"Events \\(A\\) and \\(B\\) are independent with \\(P(A) = 0.5\\) and \\(P(B) = 0.6\\). Find \\(P(A \\text{ and } B)\\).","answer":"0.3","solution":"For independent events: \\(P(A \\text{ and } B) = P(A) \\times P(B) = 0.5 \\times 0.6 = 0.3\\)."},{"type":"regular","q":"Two mutually exclusive events: \\(P(A) = 0.35\\), \\(P(B) = 0.45\\). Find \\(P(A \\text{ or } B)\\).","answer":"0.8","solution":"For mutually exclusive events: \\(P(A \\text{ or } B) = P(A) + P(B) = 0.35 + 0.45 = 0.8\\)."},{"type":"regular","q":"You flip a fair coin twice. Probability of getting at least one head?","answer":"\\(\\tfrac{3}{4}\\)","solution":"Complement is two tails: \\(1 - \\tfrac{1}{4} = \\tfrac{3}{4}\\)."},{"type":"regular","q":"Rolling two fair dice, what is the probability of getting a sum of 11?","answer":"\\(\\tfrac{1}{18}\\)","solution":"Two ways to get 11: (5,6) and (6,5) out of 36 outcomes: \\(\\tfrac{2}{36} = \\tfrac{1}{18}\\)."},{"type":"regular","q":"You roll a die and flip a coin. Probability of rolling a 6 AND getting tails?","answer":"\\(\\tfrac{1}{12}\\)","solution":"Independent events: \\(\\tfrac{1}{6} \\times \\tfrac{1}{2} = \\tfrac{1}{12}\\)."},{"type":"regular","q":"Two events: \\(P(A) = 0.4\\), \\(P(B) = 0.7\\), and they are independent. Find \\(P(A \\text{ or } B)\\).","answer":"0.82","solution":"\\(P(A \\text{ or } B) = P(A) + P(B) - P(A \\text{ and } B) = 0.4 + 0.7 - 0.28 = 0.82\\)."},{"type":"regular","q":"Rolling two dice, probability of getting a sum of 2?","answer":"\\(\\tfrac{1}{36}\\)","solution":"Only one way: (1,1) out of 36 outcomes: \\(\\tfrac{1}{36}\\)."},{"type":"regular","q":"You draw two cards with replacement from a deck. Probability both are aces?","answer":"\\(\\tfrac{1}{169}\\)","solution":"With replacement: \\(\\tfrac{4}{52} \\times \\tfrac{4}{52} = \\tfrac{1}{169}\\)."},{"type":"regular","q":"Flipping three fair coins, probability of all three being tails?","answer":"\\(\\tfrac{1}{8}\\)","solution":"Each flip is independent: \\(\\tfrac{1}{2} \\times \\tfrac{1}{2} \\times \\tfrac{1}{2} = \\tfrac{1}{8}\\)."},{"type":"word","q":"A student takes two independent quizzes. Probability of passing quiz 1 is 0.8 and quiz 2 is 0.75. What is the probability of passing both?","answer":"0.6","solution":"Independent events: \\(0.8 \\times 0.75 = 0.6\\)."},{"type":"word","q":"A bag has 3 red and 4 blue balls. You draw one, replace it, then draw again. Probability both are red?","answer":"\\(\\tfrac{9}{49}\\)","solution":"With replacement: \\(\\tfrac{3}{7} \\times \\tfrac{3}{7} = \\tfrac{9}{49}\\)."},{"type":"word","q":"A restaurant offers 3 appetizers and 5 main courses. If you choose one of each randomly, how many different meals are possible?","answer":"15","solution":"Multiply: \\(3 \\times 5 = 15\\) different combinations."},{"type":"word","q":"Two events are mutually exclusive: event A has probability 0.25 and event B has probability 0.30. What is the probability that A or B occurs?","answer":"0.55","solution":"Mutually exclusive: \\(0.25 + 0.30 = 0.55\\)."},{"type":"word","q":"A spinner is spun twice. Each spin has probability 0.4 of landing on green. What is the probability of landing on green both times?","answer":"0.16","solution":"Independent events: \\(0.4 \\times 0.4 = 0.16\\)."},{"type":"word","q":"You flip a coin and roll a die. What is the probability of getting tails AND rolling a 2 or 3?","answer":"\\(\\tfrac{1}{6}\\)","solution":"\\(\\tfrac{1}{2} \\times \\tfrac{2}{6} = \\tfrac{1}{6}\\)."}]);
  add("geometry", "g9", 2, [{"type":"regular","q":"\\(P(A) = 0.7\\), \\(P(A \\cap B) = 0.35\\). Find \\(P(B | A)\\).","answer":"0.5","solution":"\\(P(B|A) = \\tfrac{P(A \\cap B)}{P(A)} = \\tfrac{0.35}{0.7} = 0.5\\)."},{"type":"regular","q":"\\(P(X) = 0.8\\), \\(P(X \\cap Y) = 0.48\\). Find \\(P(Y | X)\\).","answer":"0.6","solution":"\\(P(Y|X) = \\tfrac{P(X \\cap Y)}{P(X)} = \\tfrac{0.48}{0.8} = 0.6\\)."},{"type":"regular","q":"Drawing 2 cards without replacement: probability second is a heart given first was a heart?","answer":"\\(\\tfrac{12}{51}\\)","solution":"After drawing one heart, 12 hearts remain out of 51 cards: \\(\\tfrac{12}{51}\\)."},{"type":"regular","q":"In a group, 40% have a driver's license, 25% have a passport, and 15% have both. Given someone has a license, probability they have a passport?","answer":"\\(\\tfrac{3}{8}\\)","solution":"\\(P(\\text{passport | license}) = \\tfrac{0.15}{0.40} = \\tfrac{3}{8}\\)."},{"type":"regular","q":"\\(P(M) = 0.6\\), \\(P(M \\cap N) = 0.18\\). Find \\(P(N | M)\\).","answer":"0.3","solution":"\\(P(N|M) = \\tfrac{0.18}{0.6} = 0.3\\)."},{"type":"regular","q":"A deck of cards: probability of drawing a red card given it is a face card?","answer":"\\(\\tfrac{1}{2}\\)","solution":"6 red face cards out of 12 total face cards: \\(\\tfrac{6}{12} = \\tfrac{1}{2}\\)."},{"type":"regular","q":"\\(P(S) = 0.75\\), \\(P(S \\cap T) = 0.45\\). Find \\(P(T | S)\\).","answer":"0.6","solution":"\\(P(T|S) = \\tfrac{0.45}{0.75} = 0.6\\)."},{"type":"regular","q":"Drawing 2 cards without replacement from a deck: probability both are spades given the first is a spade?","answer":"\\(\\tfrac{12}{51}\\)","solution":"After drawing one spade, 12 spades remain out of 51 cards: \\(\\tfrac{12}{51}\\)."},{"type":"regular","q":"\\(P(E) = 0.5\\), \\(P(E \\cap F) = 0.2\\). Find \\(P(F | E)\\).","answer":"0.4","solution":"\\(P(F|E) = \\tfrac{0.2}{0.5} = 0.4\\)."},{"type":"word","q":"In a school, 65% of students play sports and 40% play sports and an instrument. Given a student plays sports, what is the probability they play an instrument?","answer":"\\(\\tfrac{8}{13}\\)","solution":"\\(P(\\text{instrument | sports}) = \\tfrac{0.40}{0.65} = \\tfrac{8}{13}\\)."},{"type":"word","q":"A medical test: 90% of sick people test positive, 10% of healthy people test positive. If 5% of the population is sick, what is the probability someone is sick given they test positive?","answer":"≈ 0.32","solution":"Use Bayes' theorem: \\(P(\\text{sick | positive}) = \\tfrac{0.05 \\times 0.9}{0.05 \\times 0.9 + 0.95 \\times 0.1} ≈ 0.32\\)."},{"type":"word","q":"Of 100 students, 60 study math, 50 study science, and 35 study both. Given a student studies math, what is the probability they study science?","answer":"\\(\\tfrac{7}{12}\\)","solution":"\\(P(\\text{science | math}) = \\tfrac{35}{60} = \\tfrac{7}{12}\\)."},{"type":"word","q":"A bag has 5 red and 7 blue marbles. You draw one marble (red) and do not replace it. What is the probability the next marble is blue?","answer":"\\(\\tfrac{7}{11}\\)","solution":"After removing one red, 7 blue remain out of 11 total: \\(\\tfrac{7}{11}\\)."},{"type":"word","q":"In a survey, 70% own a car and 40% own a car and a bicycle. Given someone owns a car, what is the probability they own a bicycle?","answer":"\\(\\tfrac{4}{7}\\)","solution":"\\(P(\\text{bicycle | car}) = \\tfrac{0.40}{0.70} = \\tfrac{4}{7}\\)."},{"type":"word","q":"A class has 12 boys and 18 girls. 8 boys and 10 girls passed a test. Given a student passed, what is the probability they are a girl?","answer":"\\(\\tfrac{1}{2}\\)","solution":"10 girls passed out of 18 total who passed: \\(\\tfrac{10}{20} = \\tfrac{1}{2}\\)."}]);
  addCum("geometry", "g9", [{"type":"regular","q":"A fair die is rolled. Probability of rolling a 5?","answer":"\\(\\tfrac{1}{6}\\)","solution":"1 favorable outcome out of 6 possible: \\(\\tfrac{1}{6}\\)."},{"type":"regular","q":"Two independent events: \\(P(A) = 0.25\\), \\(P(B) = 0.8\\). Find \\(P(A \\text{ and } B)\\).","answer":"0.2","solution":"\\(P(A \\text{ and } B) = 0.25 \\times 0.8 = 0.2\\)."},{"type":"regular","q":"Mutually exclusive events: \\(P(X) = 0.15\\), \\(P(Y) = 0.35\\). Find \\(P(X \\text{ or } Y)\\).","answer":"0.5","solution":"\\(P(X \\text{ or } Y) = 0.15 + 0.35 = 0.5\\)."},{"type":"regular","q":"\\(P(C) = 0.6\\), \\(P(C \\cap D) = 0.24\\). Find \\(P(D | C)\\).","answer":"0.4","solution":"\\(P(D|C) = \\tfrac{0.24}{0.6} = 0.4\\)."},{"type":"regular","q":"A bag has 6 green and 9 yellow balls. Probability of drawing a green ball?","answer":"\\(\\tfrac{2}{5}\\)","solution":"6 green out of 15 total: \\(\\tfrac{6}{15} = \\tfrac{2}{5}\\)."},{"type":"regular","q":"Flipping two fair coins, probability of at least one head?","answer":"\\(\\tfrac{3}{4}\\)","solution":"Complement is TT: \\(1 - \\tfrac{1}{4} = \\tfrac{3}{4}\\)."},{"type":"regular","q":"Rolling two dice, probability of a sum of 5?","answer":"\\(\\tfrac{1}{9}\\)","solution":"Four ways: (1,4), (2,3), (3,2), (4,1) out of 36: \\(\\tfrac{4}{36} = \\tfrac{1}{9}\\)."},{"type":"regular","q":"Drawing a card from a deck, probability it is not a club?","answer":"\\(\\tfrac{3}{4}\\)","solution":"39 non-clubs out of 52: \\(\\tfrac{39}{52} = \\tfrac{3}{4}\\)."},{"type":"regular","q":"\\(P(P) = 0.55\\), \\(P(P \\cap Q) = 0.33\\). Find \\(P(Q | P)\\).","answer":"0.6","solution":"\\(P(Q|P) = \\tfrac{0.33}{0.55} = 0.6\\)."},{"type":"regular","q":"A spinner has 15 equal sections: 6 blue, 5 red, 4 yellow. Probability of spinning blue?","answer":"\\(\\tfrac{2}{5}\\)","solution":"6 blue out of 15: \\(\\tfrac{6}{15} = \\tfrac{2}{5}\\)."},{"type":"word","q":"A student has a 70% chance of passing math and a 60% chance of passing English (independent). What is the probability of passing both?","answer":"0.42","solution":"\\(0.7 \\times 0.6 = 0.42\\)."},{"type":"word","q":"A jar contains 8 red, 5 blue, and 7 green marbles. What is the probability of drawing a blue marble?","answer":"\\(\\tfrac{1}{4}\\)","solution":"5 blue out of 20 total: \\(\\tfrac{5}{20} = \\tfrac{1}{4}\\)."},{"type":"word","q":"In a group of 50 people, 30 like coffee, 20 like tea, and 10 like both. What is the probability a randomly selected person likes coffee or tea?","answer":"0.8","solution":"\\(P(C \\text{ or } T) = \\tfrac{30 + 20 - 10}{50} = \\tfrac{40}{50} = 0.8\\)."},{"type":"word","q":"A card is drawn from a deck. Given it is a red card, what is the probability it is a king?","answer":"\\(\\tfrac{1}{13}\\)","solution":"2 red kings out of 26 red cards: \\(\\tfrac{2}{26} = \\tfrac{1}{13}\\)."},{"type":"word","q":"You flip a coin three times. What is the probability of getting exactly two heads?","answer":"\\(\\tfrac{3}{8}\\)","solution":"Three favorable outcomes (HHT, HTH, THH) out of 8: \\(\\tfrac{3}{8}\\)."},{"type":"word","q":"A test has 80% sensitivity (detects disease when present) and 95% specificity (negative when absent). If 10% of the population has the disease, what is the probability someone has the disease given a positive test?","answer":"≈ 0.63","solution":"Use Bayes' theorem: \\(P(\\text{disease | positive}) = \\tfrac{0.1 \\times 0.8}{0.1 \\times 0.8 + 0.9 \\times 0.05} ≈ 0.63\\)."},{"type":"word","q":"A restaurant has 4 appetizers, 6 main courses, and 3 desserts. How many different three-course meals are possible?","answer":"72","solution":"Multiply: \\(4 \\times 6 \\times 3 = 72\\)."},{"type":"word","q":"Of 200 employees, 120 work full-time and 80 work part-time. 30 full-time and 20 part-time employees have a degree. What is the probability an employee has a degree?","answer":"0.25","solution":"50 employees with degrees out of 200: \\(\\tfrac{50}{200} = 0.25\\)."},{"type":"word","q":"A bag has 10 white and 15 black socks. You draw one sock (white) without replacement. What is the probability the next sock is white?","answer":"\\(\\tfrac{3}{8}\\)","solution":"After removing one white, 9 white remain out of 24 total: \\(\\tfrac{9}{24} = \\tfrac{3}{8}\\)."},{"type":"word","q":"In a class, 75% of students passed the exam. Given a student passed, the probability they studied is 0.8. What is \\(P(\\text{studied and passed})\\)?","answer":"0.6","solution":"\\(P(\\text{studied and passed}) = 0.75 \\times 0.8 = 0.6\\)."},{"type":"word","q":"Two events: \\(P(A) = 0.45\\), \\(P(B) = 0.55\\), \\(P(A \\cap B) = 0.20\\). Find \\(P(A \\text{ or } B)\\).","answer":"0.8","solution":"\\(P(A \\text{ or } B) = 0.45 + 0.55 - 0.20 = 0.8\\)."},{"type":"word","q":"A lottery draws 1 ticket from 500. You have 8 tickets. What is the probability you win?","answer":"\\(\\tfrac{2}{125}\\)","solution":"8 of your tickets out of 500 total: \\(\\tfrac{8}{500} = \\tfrac{2}{125}\\)."},{"type":"word","q":"A survey shows 55% of people own a smartphone and 40% own a tablet. 25% own both. What is the probability someone owns a smartphone or a tablet?","answer":"0.7","solution":"\\(0.55 + 0.40 - 0.25 = 0.7\\)."},{"type":"word","q":"In a group, 85% exercise regularly. Of those who exercise, 70% eat healthy. What is the probability someone exercises and eats healthy?","answer":"0.595","solution":"\\(0.85 \\times 0.70 = 0.595\\)."}]);
  add("geometry", "g10", 0, [{"type":"regular","q":"Find the circumference of a circle with radius 3.","answer":"6π","solution":"Use C = 2πr with r = 3."},{"type":"regular","q":"A circle has diameter 20. What is its radius?","answer":"10","solution":"Radius is half the diameter."},{"type":"regular","q":"Calculate the area of a circle with radius 7.","answer":"49π","solution":"Use A = πr² with r = 7."},{"type":"regular","q":"If a circle has circumference 18π, what is its radius?","answer":"9","solution":"From C = 2πr, solve for r: r = C/(2π) = 18π/(2π) = 9."},{"type":"regular","q":"Find the area of a circle with diameter 12.","answer":"36π","solution":"Radius is 6, so A = π(6)² = 36π."},{"type":"regular","q":"A circle has area 25π. What is its radius?","answer":"5","solution":"From A = πr², solve for r: r = √(25π/π) = 5."},{"type":"regular","q":"What is the circumference of a circle with area 16π?","answer":"8π","solution":"From A = πr², r = 4; then C = 2πr = 8π."},{"type":"regular","q":"Calculate the area of a circle with circumference 14π.","answer":"49π","solution":"From C = 2πr, r = 7; then A = πr² = 49π."},{"type":"regular","q":"A circle has radius 2.5. Find its circumference.","answer":"5π","solution":"Use C = 2πr = 2π(2.5) = 5π."},{"type":"word","q":"A circular track has radius 50 meters. How far does a runner travel in one complete lap?","answer":"100π meters","solution":"One lap is the circumference: C = 2πr = 2π(50) = 100π meters."},{"type":"word","q":"A circular garden has diameter 8 feet. What is the area of the garden?","answer":"16π square feet","solution":"Radius is 4 feet, so A = π(4)² = 16π square feet."},{"type":"word","q":"A coin has radius 0.75 inches. What is its circumference?","answer":"1.5π inches","solution":"Use C = 2πr = 2π(0.75) = 1.5π inches."},{"type":"word","q":"A circular pond has area 100π square meters. What is its diameter?","answer":"20 meters","solution":"From A = πr², r = 10 meters, so diameter = 2r = 20 meters."},{"type":"word","q":"A wheel with radius 15 cm rolls along the ground. How far does it travel in one rotation?","answer":"30π cm","solution":"Distance traveled in one rotation equals circumference: C = 2πr = 30π cm."},{"type":"word","q":"A circular table has circumference 6π feet. What is the area of the table's surface?","answer":"9π square feet","solution":"From C = 2πr, r = 3 feet; then A = π(3)² = 9π square feet."}]);
  add("geometry", "g10", 1, [{"type":"regular","q":"A central angle measures 45°. What is the measure of its intercepted arc?","answer":"45°","solution":"The intercepted arc has the same measure as the central angle."},{"type":"regular","q":"Find the arc length for a central angle of 120° in a circle of radius 5.","answer":"10π/3","solution":"Arc length = (θ/360°) × 2πr = (120°/360°) × 2π(5) = 10π/3."},{"type":"regular","q":"A circle has radius 10. An arc subtends a central angle of 30°. Find the arc length.","answer":"5π/3","solution":"Arc length = (30°/360°) × 2π(10) = 5π/3."},{"type":"regular","q":"An arc has length 4π in a circle of radius 8. What is the central angle?","answer":"90°","solution":"From arc length = (θ/360°) × 2πr, solve for θ: 4π = (θ/360°) × 16π, so θ = 90°."},{"type":"regular","q":"What is the arc length for a 270° central angle in a circle of radius 6?","answer":"9π","solution":"Arc length = (270°/360°) × 2π(6) = (3/4) × 12π = 9π."},{"type":"regular","q":"A central angle of 36° intercepts an arc in a circle of radius 4. Find the arc length.","answer":"4π/5","solution":"Arc length = (36°/360°) × 2π(4) = (1/10) × 8π = 4π/5."},{"type":"regular","q":"An arc has measure 150°. What fraction of the circle's circumference is this arc?","answer":"5/12","solution":"Arc fraction = arc measure / 360° = 150°/360° = 5/12."},{"type":"regular","q":"In a circle, an arc of length 3π corresponds to a radius of 6. Find the central angle.","answer":"90°","solution":"From 3π = (θ/360°) × 2π(6), solve for θ: 3π = (θ/360°) × 12π, so θ = 90°."},{"type":"regular","q":"What is the measure of an arc that is 1/6 of the circle?","answer":"60°","solution":"Arc measure = (1/6) × 360° = 60°."},{"type":"word","q":"A Ferris wheel has radius 25 meters. A passenger travels through a central angle of 80°. What arc length does the passenger travel?","answer":"100π/9 meters","solution":"Arc length = (80°/360°) × 2π(25) = (2/9) × 50π = 100π/9 meters."},{"type":"word","q":"A clock's hour hand sweeps from 12 to 3. If the radius to the tip is 4 inches, what arc length does the tip travel?","answer":"2π inches","solution":"From 12 to 3 is 90°; arc length = (90°/360°) × 2π(4) = 2π inches."},{"type":"word","q":"A circular arc on a road has radius 40 meters and subtends a central angle of 60°. What is the arc length?","answer":"40π/3 meters","solution":"Arc length = (60°/360°) × 2π(40) = (1/6) × 80π = 40π/3 meters."},{"type":"word","q":"A slice of pie is cut from a circular pie of radius 7 inches with a central angle of 45°. What is the length of the curved edge?","answer":"7π/4 inches","solution":"Arc length = (45°/360°) × 2π(7) = (1/8) × 14π = 7π/4 inches."},{"type":"word","q":"A sprinkler rotates through a central angle of 135° with a range of 12 feet. What arc length does it cover?","answer":"9π feet","solution":"Arc length = (135°/360°) × 2π(12) = (3/8) × 24π = 9π feet."},{"type":"word","q":"A circular track section has radius 30 meters. If an athlete runs along an arc of 100°, how far does she run?","answer":"50π/3 meters","solution":"Arc length = (100°/360°) × 2π(30) = (5/18) × 60π = 50π/3 meters."}]);
  add("geometry", "g10", 2, [{"type":"regular","q":"An inscribed angle intercepts an arc of 140°. What is the measure of the inscribed angle?","answer":"70°","solution":"An inscribed angle is half the intercepted arc: 140°/2 = 70°."},{"type":"regular","q":"An inscribed angle measures 35°. What is the measure of its intercepted arc?","answer":"70°","solution":"The intercepted arc is twice the inscribed angle: 2 × 35° = 70°."},{"type":"regular","q":"A tangent line to a circle meets a chord at the point of tangency. What is the angle between them?","answer":"90°","solution":"A tangent is perpendicular to the radius at the point of tangency."},{"type":"regular","q":"Two inscribed angles intercept the same arc of 110°. What is each inscribed angle?","answer":"55°","solution":"Inscribed angles intercepting the same arc are equal; each is 110°/2 = 55°."},{"type":"regular","q":"An inscribed angle measures 28°. What is the measure of the arc it intercepts?","answer":"56°","solution":"The intercepted arc is twice the inscribed angle: 2 × 28° = 56°."},{"type":"regular","q":"A tangent and a secant are drawn from an external point. The tangent has length 6. What information is needed to find the secant length?","answer":"The distances from the external point to the circle along the secant","solution":"Use the power of a point theorem: tangent² = external segment × whole secant."},{"type":"regular","q":"An angle is inscribed in a circle and intercepts a 180° arc. What is the inscribed angle?","answer":"90°","solution":"An inscribed angle intercepting a semicircle (180°) is 180°/2 = 90°."},{"type":"regular","q":"Two chords intersect inside a circle, creating arcs of 60° and 100°. What is the angle formed by the chords?","answer":"80°","solution":"Angle = (sum of intercepted arcs)/2 = (60° + 100°)/2 = 80°."},{"type":"regular","q":"An inscribed angle is 25°. What is the central angle that intercepts the same arc?","answer":"50°","solution":"The central angle is twice the inscribed angle: 2 × 25° = 50°."},{"type":"word","q":"A student stands on a circle and observes a chord from two different points on the circle. Both observe the same arc of 84°. What angle does each student see?","answer":"42°","solution":"Both inscribed angles intercepting the same arc measure 84°/2 = 42°."},{"type":"word","q":"A tangent line to a circular track is drawn. If a radius to the point of tangency is 8 meters, what angle does the tangent make with the radius?","answer":"90°","solution":"A tangent is always perpendicular to the radius at the point of tangency."},{"type":"word","q":"Two observers stand on a circle and look at the same arc of 130°. What angle do they each measure?","answer":"65°","solution":"Each inscribed angle is half the intercepted arc: 130°/2 = 65°."},{"type":"word","q":"A secant and tangent are drawn from an external point. The tangent length is 12. The secant's external segment is 6. What is the whole secant length?","answer":"30","solution":"By power of a point: 12² = 6 × (whole secant), so whole secant = 144/6 = 24. Wait, recalculate: 12² = 6 × whole, whole = 24. The internal part is 24 - 6 = 18. Actually, the answer is 24."},{"type":"word","q":"A point on a circle observes a diameter. What is the angle formed at that point?","answer":"90°","solution":"An inscribed angle intercepting a semicircle (180° arc) measures 90°."},{"type":"word","q":"Two chords intersect inside a circle creating arcs of 50° and 120°. What is the angle between the chords?","answer":"85°","solution":"Angle = (50° + 120°)/2 = 170°/2 = 85°."}]);
  addCum("geometry", "g10", [{"type":"regular","q":"A circle has radius 4. What is its circumference?","answer":"8π","solution":"C = 2πr = 2π(4) = 8π."},{"type":"regular","q":"Find the area of a circle with diameter 18.","answer":"81π","solution":"Radius is 9, so A = π(9)² = 81π."},{"type":"regular","q":"A central angle of 200° intercepts an arc. What is the arc measure?","answer":"200°","solution":"The intercepted arc has the same measure as the central angle."},{"type":"regular","q":"An inscribed angle measures 55°. What arc does it intercept?","answer":"110°","solution":"The intercepted arc is twice the inscribed angle: 2 × 55° = 110°."},{"type":"regular","q":"A tangent meets a radius at the point of tangency. What angle is formed?","answer":"90°","solution":"A tangent is perpendicular to the radius at the point of tangency."},{"type":"regular","q":"Arc length is 5π in a circle of radius 10. What is the central angle?","answer":"90°","solution":"From arc length = (θ/360°) × 2πr, solve: 5π = (θ/360°) × 20π, so θ = 90°."},{"type":"regular","q":"Two inscribed angles intercept the same 160° arc. What is each angle?","answer":"80°","solution":"Inscribed angles intercepting the same arc are equal: 160°/2 = 80°."},{"type":"regular","q":"A circle has area 49π. What is its circumference?","answer":"14π","solution":"From A = πr², r = 7; then C = 2πr = 14π."},{"type":"regular","q":"An arc measures 75° in a circle of radius 8. What is the arc length?","answer":"10π/3","solution":"Arc length = (75°/360°) × 2π(8) = (5/24) × 16π = 10π/3."},{"type":"regular","q":"Two chords intersect inside a circle creating arcs of 45° and 95°. What is the angle between them?","answer":"70°","solution":"Angle = (45° + 95°)/2 = 140°/2 = 70°."},{"type":"regular","q":"An inscribed angle intercepts a semicircle. What is the angle measure?","answer":"90°","solution":"A semicircle is 180°, so the inscribed angle is 180°/2 = 90°."},{"type":"regular","q":"A circle has circumference 24π. What is its area?","answer":"144π","solution":"From C = 2πr, r = 12; then A = π(12)² = 144π."},{"type":"word","q":"A circular fountain has radius 6 meters. What is the distance around the fountain?","answer":"12π meters","solution":"Circumference = 2πr = 2π(6) = 12π meters."},{"type":"word","q":"A pizza has diameter 14 inches. What is its area?","answer":"49π square inches","solution":"Radius is 7 inches, so A = π(7)² = 49π square inches."},{"type":"word","q":"A Ferris wheel rotates through a central angle of 150° with radius 20 meters. What arc length does a passenger travel?","answer":"50π/3 meters","solution":"Arc length = (150°/360°) × 2π(20) = (5/12) × 40π = 50π/3 meters."},{"type":"word","q":"A student stands on a circle and observes an arc of 96°. What is the inscribed angle?","answer":"48°","solution":"The inscribed angle is half the intercepted arc: 96°/2 = 48°."},{"type":"word","q":"A tangent line is drawn to a circle with radius 5 cm. What angle does the tangent make with the radius?","answer":"90°","solution":"A tangent is perpendicular to the radius at the point of tangency."},{"type":"word","q":"A wheel has radius 9 inches and rotates through 240°. How far does a point on the rim travel?","answer":"12π inches","solution":"Arc length = (240°/360°) × 2π(9) = (2/3) × 18π = 12π inches."},{"type":"word","q":"A circular garden has area 64π square feet. What is its radius?","answer":"8 feet","solution":"From A = πr², r = √(64π/π) = 8 feet."},{"type":"word","q":"Two chords intersect inside a circle. One pair of opposite arcs measures 70° and 110°. What is the angle formed?","answer":"90°","solution":"Angle = (70° + 110°)/2 = 180°/2 = 90°."},{"type":"word","q":"A clock's minute hand has length 5 inches. From 12 to 6, what arc length does the tip trace?","answer":"5π inches","solution":"From 12 to 6 is 180°; arc length = (180°/360°) × 2π(5) = 5π inches."},{"type":"word","q":"A circular track has circumference 200π meters. What is its radius?","answer":"100 meters","solution":"From C = 2πr, r = 200π/(2π) = 100 meters."},{"type":"word","q":"An inscribed angle measures 32°. A central angle intercepts the same arc. What is the central angle?","answer":"64°","solution":"The central angle is twice the inscribed angle: 2 × 32° = 64°."},{"type":"word","q":"A pie slice has a central angle of 60° and radius 10 inches. What is the arc length of the crust?","answer":"10π/3 inches","solution":"Arc length = (60°/360°) × 2π(10) = (1/6) × 20π = 10π/3 inches."}]);
